int32 OS_API_Impl_Init(osal_objtype_t idtype)
{
    int32 return_code;

    return_code = OS_VxWorks_TableMutex_Init(idtype);
    if (return_code != OS_SUCCESS)
    {
        return return_code;
    }

    switch (idtype)
    {
        case OS_OBJECT_TYPE_OS_TASK:
            return_code = OS_VxWorks_TaskAPI_Impl_Init();
            break;
        case OS_OBJECT_TYPE_OS_QUEUE:
            return_code = OS_VxWorks_QueueAPI_Impl_Init();
            break;
        case OS_OBJECT_TYPE_OS_BINSEM:
            return_code = OS_VxWorks_BinSemAPI_Impl_Init();
            break;
        case OS_OBJECT_TYPE_OS_COUNTSEM:
            return_code = OS_VxWorks_CountSemAPI_Impl_Init();
            break;
        case OS_OBJECT_TYPE_OS_MUTEX:
            return_code = OS_VxWorks_MutexAPI_Impl_Init();
            break;
        case OS_OBJECT_TYPE_OS_MODULE:
            return_code = OS_VxWorks_ModuleAPI_Impl_Init();
            break;
        case OS_OBJECT_TYPE_OS_TIMEBASE:
            return_code = OS_VxWorks_TimeBaseAPI_Impl_Init();
            break;
        case OS_OBJECT_TYPE_OS_STREAM:
            return_code = OS_VxWorks_StreamAPI_Impl_Init();
            break;
        case OS_OBJECT_TYPE_OS_DIR:
            return_code = OS_VxWorks_DirAPI_Impl_Init();
            break;
        default:
            break;
    }

    return return_code;
}

int32 OS_API_Init(void)
{
    int32          return_code = OS_SUCCESS;
    osal_objtype_t idtype;
    uint32         microSecPerSec;

    /*
     * If OSAL is already initialized, not really a big issue, just return.
     * This is not typically expected though, so its worth a debug statement.
     *
     * However this can validly occur when running tests on some platforms
     * without a reset/reload between invocations.
     */
    if (OS_SharedGlobalVars.GlobalState == OS_INIT_MAGIC_NUMBER)
    {
        OS_DEBUG("NOTE: ignored redundant OS_API_Init() call\n");
        return OS_SUCCESS;
    }

    /* Wipe global state structure to be sure everything is clean */
    memset(&OS_SharedGlobalVars, 0, sizeof(OS_SharedGlobalVars));

    /* Reset debug to default level if enabled */
#if defined(OSAL_CONFIG_DEBUG_PRINTF)
    OS_SharedGlobalVars.DebugLevel = 1;
#endif

    /* Set flag that says OSAL has been initialized */
    OS_SharedGlobalVars.GlobalState = OS_INIT_MAGIC_NUMBER;

    /* Initialize the common table that everything shares */
    return_code = OS_ObjectIdInit();
    if (return_code != OS_SUCCESS)
    {
        return return_code;
    }

    for (idtype = 0; idtype < OS_OBJECT_TYPE_USER; ++idtype)
    {
        /* Initialize the implementation first, as the shared layer depends on it */
        return_code = OS_API_Impl_Init(idtype);
        if (return_code != OS_SUCCESS)
        {
            OS_DEBUG("OS_API_Impl_Init(0x%x) failed to initialize: %d\n", (unsigned int)idtype, (int)return_code);
            break;
        }

        switch (idtype)
        {
            case OS_OBJECT_TYPE_OS_TASK:
                return_code = OS_TaskAPI_Init();
                break;
            case OS_OBJECT_TYPE_OS_QUEUE:
                return_code = OS_QueueAPI_Init();
                break;
            case OS_OBJECT_TYPE_OS_BINSEM:
                return_code = OS_BinSemAPI_Init();
                break;
            case OS_OBJECT_TYPE_OS_COUNTSEM:
                return_code = OS_CountSemAPI_Init();
                break;
            case OS_OBJECT_TYPE_OS_MUTEX:
                return_code = OS_MutexAPI_Init();
                break;
            case OS_OBJECT_TYPE_OS_MODULE:
                return_code = OS_ModuleAPI_Init();
                break;
            case OS_OBJECT_TYPE_OS_TIMEBASE:
                return_code = OS_TimeBaseAPI_Init();
                break;
            case OS_OBJECT_TYPE_OS_TIMECB:
                return_code = OS_TimerCbAPI_Init();
                break;
            case OS_OBJECT_TYPE_OS_STREAM:
                return_code = OS_FileAPI_Init();
                break;
            case OS_OBJECT_TYPE_OS_DIR:
                return_code = OS_DirAPI_Init();
                break;
            case OS_OBJECT_TYPE_OS_FILESYS:
                return_code = OS_FileSysAPI_Init();
                break;
            case OS_OBJECT_TYPE_OS_CONSOLE:
                return_code = OS_ConsoleAPI_Init();
                break;
            case OS_OBJECT_TYPE_OS_CONDVAR:
                return_code = OS_CondVarAPI_Init();
                break;
            default:
                break;
        }
        if (return_code != OS_SUCCESS)
        {
            OS_DEBUG("ID type 0x%x shared layer failed to initialize: %d\n", (unsigned int)idtype, (int)return_code);
            break;
        }
    }

    if (return_code == OS_SUCCESS)
    {
        return_code = OS_NetworkAPI_Init();
    }

    if (return_code == OS_SUCCESS)
    {
        return_code = OS_SocketAPI_Init();
    }

    /*
     * Confirm that somewhere during initialization,
     * the time variables got set to something valid
     */
    if (return_code == OS_SUCCESS
        && (OS_SharedGlobalVars.MicroSecPerTick == 0 || OS_SharedGlobalVars.TicksPerSecond == 0))
    {
        OS_DEBUG("Implementation failed to initialize tick time globals\n");
        return_code = OS_ERROR;
    }

    microSecPerSec = OS_SharedGlobalVars.MicroSecPerTick * OS_SharedGlobalVars.TicksPerSecond;

    if (microSecPerSec != 1000000)
    {
        OS_DEBUG("Warning: Microsecs per sec value of %lu does not equal 1000000 (MicroSecPerTick: %ld   "
                 "TicksPerSecond: %ld)\n",
                 (unsigned long)microSecPerSec,
                 (long)OS_SharedGlobalVars.MicroSecPerTick,
                 (long)OS_SharedGlobalVars.TicksPerSecond);
    }

    if (return_code != OS_SUCCESS)
    {
        /*
         * Some part of init failed, so set global flag that says OSAL is in shutdown state.
         *
         * In particular if certain internal resources (such as the console utility task)
         * were created, this should cause those tasks to self-exit such that the system
         * is ultimately returned to the same state it started in.
         */
        OS_SharedGlobalVars.GlobalState = OS_SHUTDOWN_MAGIC_NUMBER;
    }

    return return_code;
}

void OS_API_Teardown(void)
{
    /*
     * This should delete any remaining user-created objects/tasks
     */
    OS_DeleteAllObjects();

    /*
     * This should cause the "internal" objects (e.g. console utility task)
     * to exit, and will prevent any new objects from being created.
     */
    OS_ApplicationShutdown(true);
}

void OS_ApplicationExit(int32 Status)
{
    if (Status == OS_SUCCESS)
    {
        exit(EXIT_SUCCESS);
    }
    else
    {
        exit(EXIT_FAILURE);
    }
}

void OS_ApplicationShutdown(uint8 flag)
{
    if (flag == true)
    {
        OS_SharedGlobalVars.GlobalState = OS_SHUTDOWN_MAGIC_NUMBER;
    }

    /*
     * Hook to allow the underlying implementation to do something.
     * Assuming the main task is sitting in OS_IdleLoop(), this implementation
     * should do whatever is needed to wake that task up.
     */
    OS_ApplicationShutdown_Impl();
}

void OS_ApplicationShutdown_Impl(void)
{
    taskResume(OS_idle_task_id);
}

void OS_Application_Startup(void)
{
    int       TicksPerSecond;
    uint32    reset_type;
    uint32    reset_subtype;
    osal_id_t fs_id;
    char      reset_register;
    int32     Status;

    /*
    ** Initialize the OS API
    */
    Status = OS_API_Init();
    if (Status != OS_SUCCESS)
    {
        /* irrecoverable error if OS_API_Init() fails. */
        /* note: use printf here, as OS_printf may not work */
        printf("CFE_PSP: OS_API_Init() failure\n");
        CFE_PSP_Panic(Status);

        /*
         * normally CFE_PSP_Panic() does not return, except
         * during unit testing.  This return avoids executing
         * the rest of this function in that case.
         */
        return;
    }

    /*
    ** Set up the virtual FS mapping for the "/cf" directory
    ** On this platform it will use the CF:0 physical device.
    */
    Status = OS_FileSysAddFixedMap(&fs_id, "CF:0", "/cf");
    if (Status != OS_SUCCESS)
    {
        /* Print for informational purposes --
         * startup can continue, but loads may fail later, depending on config. */
        OS_printf("CFE_PSP: OS_FileSysAddFixedMap() failure: %d\n", (int)Status);
    }

    /*
    ** Delay for one second.
    */
    TicksPerSecond = sysClkRateGet();
    (void)taskDelay(TicksPerSecond);

    /*
    ** This starts up the hardware timer on the board that
    ** will be used to get the local time
    */
    sysPciWrite32(0xFC0011D0, 0x0D6937E5);

    /*
    ** Setup the pointer to the reserved area in vxWorks.
    ** This must be done before any of the reset variables are used.
    */
    CFE_PSP_SetupReservedMemoryMap();

    /*
    ** Initialize the statically linked modules (if any)
    */
    CFE_PSP_ModuleInit();

    /*
    ** Determine Reset type by reading the hardware reset register.
    */
    reset_register = *(SYS_REG_BLRR);
    OS_printf("CFE_PSP: Reset Register = %02X\n", reset_register);

    if (reset_register & SYS_REG_BLRR_PWRON)
    {
        OS_printf("CFE_PSP: POWERON Reset: Power Switch ON.\n");
        reset_type    = CFE_PSP_RST_TYPE_POWERON;
        reset_subtype = CFE_PSP_RST_SUBTYPE_POWER_CYCLE;
    }
    else if (reset_register & SYS_REG_BLRR_PBRST)
    {
        OS_printf("CFE_PSP: POWERON Reset: CPCI Push Button Reset.\n");
        reset_type    = CFE_PSP_RST_TYPE_POWERON;
        reset_subtype = CFE_PSP_RST_SUBTYPE_PUSH_BUTTON;
    }
    else if (reset_register & SYS_REG_BLRR_FBTN)
    {
        OS_printf("CFE_PSP: POWERON Reset: Front Panel Push Button Reset.\n");
        reset_type    = CFE_PSP_RST_TYPE_POWERON;
        reset_subtype = CFE_PSP_RST_SUBTYPE_PUSH_BUTTON;
    }
    else if (reset_register & SYS_REG_BLRR_WDT2)
    {
        OS_printf("CFE_PSP: PROCESSOR Reset: Watchdog level 2 Reset.\n");
        reset_type    = CFE_PSP_RST_TYPE_PROCESSOR;
        reset_subtype = CFE_PSP_RST_SUBTYPE_HW_WATCHDOG;
    }
    else if (reset_register & SYS_REG_BLRR_SWSRST)
    {
        OS_printf("CFE_PSP: PROCESSOR Reset: Software Soft Reset.\n");
        reset_type    = CFE_PSP_RST_TYPE_PROCESSOR;
        reset_subtype = CFE_PSP_RST_SUBTYPE_RESET_COMMAND;
    }
    else if (reset_register & SYS_REG_BLRR_SWHRST)
    {
        /*
        ** For a Software hard reset, we want to look at the special
        ** BSP reset variable to determine if we wanted a
        ** Power ON or a Processor reset. Because the vxWorks sysToMonitor and
        ** reboot functions use this reset type, we want to use this for a software
        ** commanded processor or Power on reset.
        */
        if (CFE_PSP_ReservedMemoryMap.BootPtr->bsp_reset_type == CFE_PSP_RST_TYPE_POWERON)
        {
            OS_printf("CFE_PSP: POWERON Reset: Software Hard Reset.\n");
            reset_type    = CFE_PSP_RST_TYPE_POWERON;
            reset_subtype = CFE_PSP_RST_SUBTYPE_RESET_COMMAND;
        }
        else
        {
            OS_printf("CFE_PSP: PROCESSOR Reset: Software Hard Reset.\n");
            reset_type    = CFE_PSP_RST_TYPE_PROCESSOR;
            reset_subtype = CFE_PSP_RST_SUBTYPE_RESET_COMMAND;
        }
    }
    else
    {
        OS_printf("CFE_PSP: POWERON Reset: UNKNOWN Reset.\n");
        reset_type    = CFE_PSP_RST_TYPE_POWERON;
        reset_subtype = CFE_PSP_RST_SUBTYPE_UNDEFINED_RESET;
    }

    /*
     * If CFE fails to boot with a processor reset,
     * then make sure next time it uses a power on reset.
     */
    if (reset_type == CFE_PSP_RST_TYPE_PROCESSOR)
    {
        CFE_PSP_ReservedMemoryMap.BootPtr->bsp_reset_type = CFE_PSP_RST_TYPE_POWERON;
    }

    /*
    ** Initialize the reserved memory
    */
    CFE_PSP_InitProcessorReservedMemory(reset_type);

    /*
    ** Call cFE entry point. This will return when cFE startup
    ** is complete.
    */
    CFE_PSP_MAIN_FUNCTION(reset_type, reset_subtype, 1, CFE_PSP_NONVOL_STARTUP_FILE);
}

int32 OS_BinSemAPI_Init(void)
{
    memset(OS_bin_sem_table, 0, sizeof(OS_bin_sem_table));
    return OS_SUCCESS;
}

int32 OS_BinSemCreate(osal_id_t *sem_id, const char *sem_name, uint32 sem_initial_value, uint32 options)
{
    int32                         return_code;
    OS_object_token_t             token;
    OS_bin_sem_internal_record_t *binsem;

    /* Check parameters */
    OS_CHECK_POINTER(sem_id);
    OS_CHECK_APINAME(sem_name);

    /* Note - the common ObjectIdAllocate routine will lock the object type and leave it locked. */
    return_code = OS_ObjectIdAllocateNew(LOCAL_OBJID_TYPE, sem_name, &token);
    if (return_code == OS_SUCCESS)
    {
        binsem = OS_OBJECT_TABLE_GET(OS_bin_sem_table, token);

        /* Reset the table entry and save the name */
        OS_OBJECT_INIT(token, binsem, obj_name, sem_name);

        /* Now call the OS-specific implementation.  This reads info from the table. */
        return_code = OS_BinSemCreate_Impl(&token, sem_initial_value, options);

        /* Check result, finalize record, and unlock global table. */
        return_code = OS_ObjectIdFinalizeNew(return_code, &token, sem_id);
    }

    return return_code;
}

int32 OS_BinSemCreate_Impl(const OS_object_token_t *token, uint32 sem_initial_value, uint32 options)
{
    SEM_ID                            tmp_sem_id;
    OS_impl_binsem_internal_record_t *impl;

    impl = OS_OBJECT_TABLE_GET(OS_impl_bin_sem_table, *token);

    /* Initialize VxWorks Semaphore.
     * The memory for this sem is statically allocated. */
    tmp_sem_id = semBInitialize(impl->bmem, SEM_Q_PRIORITY, sem_initial_value);

    /* check if semBInitialize failed */
    if (tmp_sem_id == (SEM_ID)0)
    {
        OS_DEBUG("semBInitialize() - vxWorks errno %d\n", errno);
        return OS_SEM_FAILURE;
    }

    impl->vxid = tmp_sem_id;
    return OS_SUCCESS;
}

int32 OS_BinSemDelete(osal_id_t sem_id)
{
    OS_object_token_t token;
    int32             return_code;

    return_code = OS_ObjectIdGetById(OS_LOCK_MODE_EXCLUSIVE, LOCAL_OBJID_TYPE, sem_id, &token);
    if (return_code == OS_SUCCESS)
    {
        return_code = OS_BinSemDelete_Impl(&token);

        /* Complete the operation via the common routine */
        return_code = OS_ObjectIdFinalizeDelete(return_code, &token);
    }

    return return_code;
}

int32 OS_BinSemDelete_Impl(const OS_object_token_t *token)
{
    OS_impl_binsem_internal_record_t *impl;

    impl = OS_OBJECT_TABLE_GET(OS_impl_bin_sem_table, *token);

    /*
     * As the memory for the sem is statically allocated, delete is a no-op.
     */
    impl->vxid = 0;
    return OS_SUCCESS;
}

