int32 OS_FS_GetPhysDriveName(char *PhysDriveName, const char *MountPoint)
{
    OS_object_token_t             token;
    int32                         return_code;
    OS_filesys_internal_record_t *filesys;

    /* Check parameters */
    OS_CHECK_PATHNAME(MountPoint);
    OS_CHECK_POINTER(PhysDriveName);

    /* Get a reference lock, as a filesystem check could take some time. */
    return_code = OS_ObjectIdGetBySearch(OS_LOCK_MODE_GLOBAL,
                                         LOCAL_OBJID_TYPE,
                                         OS_FileSys_FindVirtMountPoint,
                                         (void *)MountPoint,
                                         &token);

    if (return_code == OS_SUCCESS)
    {
        filesys = OS_OBJECT_TABLE_GET(OS_filesys_table, token);

        if ((filesys->flags & OS_FILESYS_FLAG_IS_MOUNTED_SYSTEM) != 0)
        {
            strncpy(PhysDriveName, filesys->system_mountpt, OS_FS_PHYS_NAME_LEN - 1);
            PhysDriveName[OS_FS_PHYS_NAME_LEN - 1] = 0;
        }
        else
        {
            return_code = OS_ERR_INCORRECT_OBJ_STATE;
        }

        OS_ObjectIdRelease(&token);
    }
    else
    {
        return_code = OS_ERR_NAME_NOT_FOUND;
    }

    return return_code;
}

static int32 OS_FdSet_ConvertIn_Impl(int *os_maxfd, fd_set *os_set, const OS_FdSet *OSAL_set)
{
    size_t       offset;
    size_t       bit;
    osal_index_t id;
    uint8        objids;
    int          osfd;
    int32        status;

    status = OS_SUCCESS;
    for (offset = 0; offset < sizeof(OSAL_set->object_ids); ++offset)
    {
        objids = OSAL_set->object_ids[offset];
        bit    = 0;
        while (objids != 0)
        {
            id = OSAL_INDEX_C((offset * 8) + bit);
            if ((objids & 0x01) != 0 && id < OS_MAX_NUM_OPEN_FILES)
            {
                osfd = OS_impl_filehandle_table[id].fd;
                if (osfd >= 0)
                {
                    if (osfd >= FD_SETSIZE || !OS_impl_filehandle_table[id].selectable)
                    {
                        /* out of range of select() implementation */
                        status = OS_ERR_OPERATION_NOT_SUPPORTED;
                    }
                    else
                    {
                        FD_SET(osfd, os_set);
                        if (osfd > *os_maxfd)
                        {
                            *os_maxfd = osfd;
                        }
                    }
                }
            }
            ++bit;
            objids >>= 1;
        }
    }

    return status;
}

static void OS_FdSet_ConvertOut_Impl(fd_set *OS_set, OS_FdSet *OSAL_set)
{
    size_t       offset;
    size_t       bit;
    osal_index_t id;
    uint8        objids;
    int          osfd;

    for (offset = 0; offset < sizeof(OSAL_set->object_ids); ++offset)
    {
        objids = OSAL_set->object_ids[offset];
        bit    = 0;
        while (objids != 0)
        {
            id = OSAL_INDEX_C((offset * 8) + bit);
            if ((objids & 0x01) != 0 && id < OS_MAX_NUM_OPEN_FILES)
            {
                osfd = OS_impl_filehandle_table[id].fd;
                if (osfd < 0 || !FD_ISSET(osfd, OS_set))
                {
                    OSAL_set->object_ids[offset] &= ~(1 << bit);
                }
            }
            ++bit;
            objids >>= 1;
        }
    }
}

