int32 OS_FileSysAddFixedMap(osal_id_t *filesys_id, const char *phys_path, const char *virt_path)
{
    OS_filesys_internal_record_t *filesys;
    int32                         return_code;
    OS_object_token_t             token;

    /*
     * Validate inputs
     */
    OS_CHECK_POINTER(filesys_id);
    OS_CHECK_STRING(phys_path, sizeof(filesys->system_mountpt), OS_FS_ERR_PATH_TOO_LONG);
    OS_CHECK_PATHNAME(virt_path);

    return_code = OS_ObjectIdAllocateNew(LOCAL_OBJID_TYPE, virt_path, &token);
    if (return_code == OS_SUCCESS)
    {
        filesys = OS_OBJECT_TABLE_GET(OS_filesys_table, token);

        /* Reset the table entry and save the name */
        OS_OBJECT_INIT(token, filesys, virtual_mountpt, virt_path);

        strncpy(filesys->system_mountpt, phys_path, sizeof(filesys->system_mountpt) - 1);
        strncpy(filesys->virtual_mountpt, virt_path, sizeof(filesys->virtual_mountpt) - 1);

        /*
         * mark the entry that it is a fixed disk
         */
        filesys->fstype = OS_FILESYS_TYPE_FS_BASED;
        filesys->flags  = OS_FILESYS_FLAG_IS_FIXED;

        /*
         * The "mount" implementation is required as it will
         * create the mountpoint if it does not already exist
         */
        return_code = OS_FileSysStartVolume_Impl(&token);

        if (return_code == OS_SUCCESS)
        {
            filesys->flags |= OS_FILESYS_FLAG_IS_READY;
            return_code     = OS_FileSysMountVolume_Impl(&token);
        }

        if (return_code == OS_SUCCESS)
        {
            /*
             * mark the entry that it is a fixed disk
             */
            filesys->flags |= OS_FILESYS_FLAG_IS_MOUNTED_SYSTEM | OS_FILESYS_FLAG_IS_MOUNTED_VIRTUAL;
        }

        /* Check result, finalize record, and unlock global table. */
        return_code = OS_ObjectIdFinalizeNew(return_code, &token, filesys_id);
    }

    return return_code;
}

int32 OS_FileSysCheckVolume_Impl(const OS_object_token_t *token, bool repair)
{
    OS_filesys_internal_record_t *local;
    STATUS                        chk_status;
    int                           flags;
    int                           fd;

    local = OS_OBJECT_TABLE_GET(OS_filesys_table, *token);

    fd = open(local->system_mountpt, O_RDONLY, 0);
    if (fd < 0)
    {
        return OS_ERROR;
    }

    /* Fix the disk if there are errors */
    if (repair)
    {
        flags = DOS_CHK_REPAIR;
    }
    else
    {
        flags = DOS_CHK_ONLY;
    }

    flags |= DOS_CHK_VERB_SILENT;

    chk_status = ioctl(fd, FIOCHKDSK, flags);

    close(fd);

    if (chk_status != OK)
    {
        return OS_ERROR;
    }

    return OS_SUCCESS;
}

bool OS_FileSysFilterFree(void *ref, const OS_object_token_t *token, const OS_common_record_t *obj)
{
    return !OS_ObjectIdDefined(obj->active_id);
}

int32 OS_FileSysFormatVolume_Impl(const OS_object_token_t *token)
{
    OS_filesys_internal_record_t *local;
    int32                         return_code = OS_ERR_NOT_IMPLEMENTED;
    int                           status;

    local = OS_OBJECT_TABLE_GET(OS_filesys_table, *token);

    switch (local->fstype)
    {
        case OS_FILESYS_TYPE_FS_BASED:
        {
            /*
             * The "format" operation is a no-op on FS_BASED types.
             * Return success to allow the operation to continue.
             */
            return_code = OS_SUCCESS;
            break;
        }
        case OS_FILESYS_TYPE_VOLATILE_DISK:
        case OS_FILESYS_TYPE_NORMAL_DISK:
        {
            /*
            ** Call the dos format routine
            */
            status = dosFsVolFormat(local->system_mountpt, DOS_OPT_BLANK, NULL);
            if (status == -1)
            {
                OS_DEBUG("OSAL: dosFsVolFormat failed. Errno = %d\n", errnoGet());
                return_code = OS_FS_ERR_DRIVE_NOT_CREATED;
            }
            else
            {
                return_code = OS_SUCCESS;
            }
            break;
        }
        default:
            break;
    }

    return return_code;
}

int32 OS_FileSysMountVolume_Impl(const OS_object_token_t *token)
{
    OS_filesys_internal_record_t *local;
    int32                         status;
    int                           fd;
    struct stat                   stat_buf;

    local = OS_OBJECT_TABLE_GET(OS_filesys_table, *token);

    /*
     * For FS-based mounts, these are just a map to a some other
     * directory in the filesystem.
     *
     * If it does exist then make sure it is actually a directory.
     * If it does not exist then attempt to create it.
     */
    if (local->fstype == OS_FILESYS_TYPE_FS_BASED)
    {
        if (stat(local->system_mountpt, &stat_buf) == 0)
        {
            if (S_ISDIR(stat_buf.st_mode))
            {
                /* mount point exists */
                status = OS_SUCCESS;
            }
            else
            {
                OS_DEBUG("%s is not a directory\n", local->system_mountpt);
                status = OS_FS_ERR_PATH_INVALID;
            }
        }
        else
        {
            if (mkdir(local->system_mountpt, 0775) == 0)
            {
                /* directory created OK */
                status = OS_SUCCESS;
            }
            else
            {
                OS_DEBUG("mkdir(%s): errno=%d\n", local->system_mountpt, errnoGet());
                status = OS_FS_ERR_DRIVE_NOT_CREATED;
            }
        }
    }
    else
    {
        /*
         * For all other (non-FS_BASED) filesystem types,
         * Calling open() on the physical device path mounts the device.
         */
        fd = open(local->system_mountpt, O_RDONLY, 0644);
        if (fd < 0)
        {
            status = OS_ERROR;
        }
        else
        {
            status = OS_SUCCESS;
            close(fd);
        }
    }

    return status;
}

int32 OS_FileSysStartVolume_Impl(const OS_object_token_t *token)
{
    OS_filesys_internal_record_t      *local;
    OS_impl_filesys_internal_record_t *impl;
    int32                              return_code;

    impl  = OS_OBJECT_TABLE_GET(OS_impl_filesys_table, *token);
    local = OS_OBJECT_TABLE_GET(OS_filesys_table, *token);

    memset(impl, 0, sizeof(*impl));
    return_code = OS_ERR_NOT_IMPLEMENTED;
    switch (local->fstype)
    {
        case OS_FILESYS_TYPE_FS_BASED:
        {
            /* pass through for FS_BASED volumes, assume already mounted */
            OS_DEBUG("OSAL: Mapping an FS_BASED disk at: %s\n", (unsigned long)local->system_mountpt);
            return_code = OS_SUCCESS;
            break;
        }

        case OS_FILESYS_TYPE_VOLATILE_DISK:
        {
            OS_DEBUG("OSAL: Starting a RAM disk at: 0x%08lX\n", (unsigned long)local->address);

            /*
            ** Create the ram disk device
            ** The 32 is the number of blocks per track.
            **  Other values don't seem to work here
            */
            impl->blkDev           = ramDevCreate(local->address, local->blocksize, 32, local->numblocks, 0);
            impl->xbdMaxPartitions = 1;
            break;
        }

#ifdef USE_VXWORKS_ATA_DRIVER
        case OS_FILESYS_TYPE_NORMAL_DISK:
        {
            /*
            ** Create the Flash disk device
            ** This code requires an ATA driver in the BSP, so it must be
            ** left out of the compilation BSPs without.
            */
            OS_DEBUG("OSAL: Starting an ATA DISK: %s\n", local->volume_name);
            impl->xbdMaxPartitions = 4;
            impl->blkDev           = ataDevCreate(0, 0, 0, 0);
            break;
        }
#endif

        default:
            break;
    }

    if (impl->xbdMaxPartitions > 0)
    {
        /*
         * This code is common to RAM disks and ATA disks
         * (and anything else that relies on the xbd layer)
         */

        if (impl->blkDev == NULL)
        {
            /* there was an error calling the "DevCreate" function */
            OS_DEBUG("OSAL: Error creating low level block device\n");
            return_code = OS_FS_ERR_DRIVE_NOT_CREATED;
        }
        else if (local->volume_name[0] == 0)
        {
            /* this requires that the user has specified the volume name to mount */
            OS_DEBUG("OSAL: No volume name specified to mount\n");
            return_code = OS_FS_ERR_DRIVE_NOT_CREATED;
        }
        else
        {
            /*
             * Connect the low level block device to the xbd device
             */
            impl->xbd = xbdBlkDevCreateSync(impl->blkDev, local->volume_name);
            if (impl->xbd == NULLDEV)
            {
                return_code = OS_FS_ERR_DRIVE_NOT_CREATED;
            }
            else
            {
                /*
                 * Always using partition ":0"
                 *
                 * For ATA disks, this is different than the previous implementation
                 * which would try to open() all possible partitions in order until
                 * one was successful.
                 *
                 * From the original OS_GetPhysDeviceName() implementation comments:
                 *
                 *  The disk XBD code will add ":X" to the volume name you give to a disk, where
                 *  X is the partition number. While RAM disks are always 0 ( "RAM:0" ),
                 *  a physical disk such as a compact flash disk can be ":0", or ":1" etc,
                 *  depending on how the disk was partitioned.
                 *
                 * But there are two issues with trying all possible devices like that:
                 *  - Trying with open() actually mounts the filesystem, meaning it must
                 *    have a pre-existing dosFs on it
                 *  - It might not be consistent between devices/cards or even run-to-run.
                 *    (i.e. if a partition was formatted manually and then the software
                 *    restarted, a different block device might get mounted the second time)
                 */
                snprintf(local->system_mountpt, sizeof(local->system_mountpt), "%s:0", local->volume_name);

                return_code = OS_SUCCESS;
            }
        }
    }

    return return_code;
}

int32 OS_FileSysStatVolume(const char *name, OS_statvfs_t *statbuf)
{
    int32             return_code;
    OS_object_token_t token;

    /* Check parameters */
    OS_CHECK_PATHNAME(name);
    OS_CHECK_POINTER(statbuf);

    return_code = OS_ObjectIdGetBySearch(OS_LOCK_MODE_GLOBAL,
                                         LOCAL_OBJID_TYPE,
                                         OS_FileSys_FindVirtMountPoint,
                                         (void *)name,
                                         &token);

    if (return_code == OS_SUCCESS)
    {
        return_code = OS_FileSysStatVolume_Impl(&token, statbuf);

        OS_ObjectIdRelease(&token);
    }

    return return_code;
}

int32 OS_FileSysStatVolume_Impl(const OS_object_token_t *token, OS_statvfs_t *result)
{
    OS_filesys_internal_record_t *local;
    struct statfs                 stat_buf;
    int                           return_code;

    local = OS_OBJECT_TABLE_GET(OS_filesys_table, *token);

    if (statfs(local->system_mountpt, &stat_buf) != 0)
    {
        return_code = OS_ERROR;
        memset(result, 0, sizeof(*result));
    }
    else
    {
        result->block_size   = OSAL_SIZE_C(stat_buf.f_bsize);
        result->blocks_free  = OSAL_BLOCKCOUNT_C(stat_buf.f_bfree);
        result->total_blocks = OSAL_BLOCKCOUNT_C(stat_buf.f_blocks);
        return_code          = OS_SUCCESS;
    }

    return return_code;
}

int32 OS_FileSysStopVolume_Impl(const OS_object_token_t *token)
{
    OS_filesys_internal_record_t      *local;
    OS_impl_filesys_internal_record_t *impl;

    impl  = OS_OBJECT_TABLE_GET(OS_impl_filesys_table, *token);
    local = OS_OBJECT_TABLE_GET(OS_filesys_table, *token);

    switch (local->fstype)
    {
        case OS_FILESYS_TYPE_VOLATILE_DISK:
        case OS_FILESYS_TYPE_NORMAL_DISK:
        {
            if (impl->xbdMaxPartitions > 0 && impl->xbd != NULLDEV)
            {
                xbdBlkDevDelete(impl->xbd, NULL);
                impl->xbd              = NULLDEV;
                impl->xbdMaxPartitions = 0;
            }
            break;
        }
        default:
            break;
    }

    /*
     * TBD: The VxWorks documentation does not seem to indicate any
     * "DevDelete" operation as the complement to ramDevCreate/ataDevCreate.
     */

    return OS_SUCCESS;
}

int32 OS_FileSysUnmountVolume_Impl(const OS_object_token_t *token)
{
    OS_filesys_internal_record_t *local;
    int32                         status;
    int                           fd;

    local = OS_OBJECT_TABLE_GET(OS_filesys_table, *token);

    if (local->fstype == OS_FILESYS_TYPE_FS_BASED)
    {
        /* unmount is a no-op on FS-based mounts - it is just a directory map */
        status = OS_SUCCESS;
    }
    else
    {
        /*
        ** vxWorks uses an ioctl to unmount
        */
        fd = open(local->system_mountpt, O_RDONLY, 0644);
        if (fd < 0)
        {
            status = OS_ERROR;
        }
        else
        {
            if (ioctl(fd, FIOUNMOUNT, 0) < 0)
            {
                status = OS_ERROR;
            }
            else
            {
                status = OS_SUCCESS;
            }

            close(fd);
        }
    }

    return status;
}

bool OS_FileSys_FindVirtMountPoint(void *ref, const OS_object_token_t *token, const OS_common_record_t *obj)
{
    OS_filesys_internal_record_t *filesys;
    const char                   *target = (const char *)ref;
    size_t                        mplen;

    filesys = OS_OBJECT_TABLE_GET(OS_filesys_table, *token);

    if ((filesys->flags & OS_FILESYS_FLAG_IS_MOUNTED_VIRTUAL) == 0)
    {
        return false;
    }

    mplen = OS_strnlen(filesys->virtual_mountpt, sizeof(filesys->virtual_mountpt));

    /*
     * The virtual_mountpt member should be a substring of the search target.
     * If this matches a basic substring check then it may be match
     */
    if (mplen == 0 || mplen >= sizeof(filesys->virtual_mountpt)
        || strncmp(target, filesys->virtual_mountpt, mplen) != 0)
    {
        /* not a substring, so not a match */
        return false;
    }

    /*
     * Confirm that the substring ends at either a directory separator
     * or the end of string  (so exact mount points also match).
     *
     * For instance consider a virtual_mountpt of /mnt/abc and searching
     * for target=/mnt/abcd - this should return false in that case.
     */
    return (target[mplen] == '/' || target[mplen] == 0);
}

int32 OS_FileSys_Initialize(char             *address,
                            const char       *fsdevname,
                            const char       *fsvolname,
                            size_t            blocksize,
                            osal_blockcount_t numblocks,
                            bool              should_format)
{
    OS_filesys_internal_record_t *filesys;
    int32                         return_code;
    OS_object_token_t             token;

    /*
     * Check parameters
     *
     * Note "address" is not checked, because in certain configurations it can be validly null.
     */
    OS_CHECK_STRING(fsdevname, sizeof(filesys->device_name), OS_FS_ERR_PATH_TOO_LONG);
    OS_CHECK_STRING(fsvolname, sizeof(filesys->volume_name), OS_FS_ERR_PATH_TOO_LONG);

    /* check names are not empty strings */
    if (fsdevname[0] == 0 || fsvolname[0] == 0)
    {
        return OS_FS_ERR_PATH_INVALID;
    }

    return_code = OS_ObjectIdAllocateNew(LOCAL_OBJID_TYPE, fsdevname, &token);
    if (return_code == OS_SUCCESS)
    {
        filesys = OS_OBJECT_TABLE_GET(OS_filesys_table, token);

        /* Reset the table entry and save the name */
        OS_OBJECT_INIT(token, filesys, device_name, fsdevname);

        /* populate the VolumeName and BlockSize ahead of the Impl call,
         * so the implementation can reference this info if necessary */
        filesys->blocksize = blocksize;
        filesys->numblocks = numblocks;
        filesys->address   = address;
        strncpy(filesys->volume_name, fsvolname, sizeof(filesys->volume_name) - 1);

        /*
         * Determine basic type of filesystem, if not already known
         *
         * if either an address was supplied, or if the volume name
         * contains the string "RAM" then it is a RAM disk. Otherwise
         * leave the type as UNKNOWN and let the implementation decide.
         */
        if (filesys->address != NULL
            || strncmp(filesys->volume_name,
                       OS_FILESYS_RAMDISK_VOLNAME_PREFIX,
                       sizeof(OS_FILESYS_RAMDISK_VOLNAME_PREFIX) - 1)
                   == 0)
        {
            filesys->fstype = OS_FILESYS_TYPE_VOLATILE_DISK;
        }

        return_code = OS_FileSysStartVolume_Impl(&token);

        if (return_code == OS_SUCCESS)
        {
            /*
             * The "mkfs" call also formats the device.
             * this is the primary difference between mkfs and initfs.
             */
            if (should_format)
            {
                return_code = OS_FileSysFormatVolume_Impl(&token);
            }

            if (return_code == OS_SUCCESS)
            {
                filesys->flags |= OS_FILESYS_FLAG_IS_READY;
            }
            else
            {
                /*
                 * To avoid leaving in an intermediate state,
                 * this also stops the volume if formatting failed.
                 * Cast to void to repress analysis warnings for
                 * ignored return value.
                 */
                (void)OS_FileSysStopVolume_Impl(&token);
            }
        }

        /* Check result, finalize record, and unlock global table. */
        return_code = OS_ObjectIdFinalizeNew(return_code, &token, NULL);
    }

    return return_code;
}

int32 OS_FileTruncate(osal_id_t filedes, osal_offset_t length)
{
    OS_object_token_t token;
    int32             return_code;

    /* Make sure the file descriptor is legit before using it */
    /* note that ftruncate (or equivalent) is expected to be a quick and easy operation,
     * it should not TYPICALLY block for any period of time, but it can block if
     * there are other simultaneous ops on the same file occurring.  Hence why
     * this still uses a REFCOUNT lock type */
    return_code = OS_ObjectIdGetById(OS_LOCK_MODE_REFCOUNT, LOCAL_OBJID_TYPE, filedes, &token);
    if (return_code == OS_SUCCESS)
    {
        return_code = OS_FileTruncate_Impl(&token, length);
        OS_ObjectIdRelease(&token);
    }

    return return_code;
}

int32 OS_FileTruncate_Impl(const OS_object_token_t *token, osal_offset_t len)
{
    OS_impl_file_internal_record_t *impl;
    int32                           Status;

    impl = OS_OBJECT_TABLE_GET(OS_impl_filehandle_table, *token);

    if (ftruncate(impl->fd, len) >= 0)
    {
        Status = OS_SUCCESS;
    }
    else if (errno == EACCES || errno == EPERM || errno == ETXTBSY || errno == EROFS)
    {
        Status = OS_ERR_OPERATION_NOT_SUPPORTED;
    }
    else if (errno == EFBIG)
    {
        Status = OS_ERR_OUTPUT_TOO_LARGE;
    }
    else
    {
        Status = OS_ERROR;
    }

    return Status;
}

int32 OS_ForEachDoCallback(osal_id_t obj_id, void *ref)
{
    OS_creator_filter_t *filter = ref;

    /* Just invoke the user callback */
    filter->user_callback(obj_id, filter->user_arg);
    return OS_SUCCESS;
}

bool OS_ForEachFilterCreator(void *ref, const OS_object_token_t *token, const OS_common_record_t *obj)
{
    OS_creator_filter_t *filter = ref;

    /*
     * Check if the obj_id is both valid and matches
     * the specified creator_id
     */
    return (OS_ObjectIdIsValid(obj->active_id)
            && (OS_ObjectIdEqual(filter->creator_id, OS_OBJECT_CREATOR_ANY)
                || OS_ObjectIdEqual(obj->creator, filter->creator_id)));
}

void OS_ForEachObject(osal_id_t creator_id, OS_ArgCallback_t callback_ptr, void *callback_arg)
{
    osal_objtype_t idtype;

    for (idtype = 0; idtype < OS_OBJECT_TYPE_USER; ++idtype)
    {
        OS_ForEachObjectOfType(idtype, creator_id, callback_ptr, callback_arg);
    }
}

void OS_ForEachObjectOfType(osal_objtype_t   objtype,
                            osal_id_t        creator_id,
                            OS_ArgCallback_t callback_ptr,
                            void            *callback_arg)
{
    OS_object_iter_t    iter;
    OS_creator_filter_t filter;

    filter.creator_id    = creator_id;
    filter.user_callback = callback_ptr;
    filter.user_arg      = callback_arg;

    if (OS_ObjectIdIteratorInit(OS_ForEachFilterCreator, &filter, objtype, &iter) == OS_SUCCESS)
    {
        while (OS_ObjectIdIteratorGetNext(&iter))
        {
            OS_ObjectIdIteratorProcessEntry(&iter, OS_ForEachDoCallback);
        }

        OS_ObjectIdIteratorDestroy(&iter);
    }
}

int32 OS_GenericClose_Impl(const OS_object_token_t *token)
{
    int                             result;
    OS_impl_file_internal_record_t *impl;

    impl = OS_OBJECT_TABLE_GET(OS_impl_filehandle_table, *token);

    result = close(impl->fd);
    if (result < 0)
    {
        /*
         * close() can technically fail for various reasons, but
         * there isn't much recourse if this call fails.  Just log
         * the failure for debugging.
         *
         * POSIX also does not specify the state of the filehandle
         * after a close() with an error.
         *
         * At least in  Linux/glibc the filehandle is always closed
         * in the kernel and should not be used again or re-closed.
         */
        OS_DEBUG("close: %s\n", strerror(errno));
    }
    impl->fd = -1;
    return OS_SUCCESS;
}

int32 OS_GenericRead_Impl(const OS_object_token_t *token, void *buffer, size_t nbytes, OS_time_t abs_timeout)
{
    int32                           return_code;
    ssize_t                         os_result;
    uint32                          operation;
    OS_impl_file_internal_record_t *impl;

    impl = OS_OBJECT_TABLE_GET(OS_impl_filehandle_table, *token);

    return_code = OS_SUCCESS;

    if (nbytes > 0)
    {
        operation = OS_STREAM_STATE_READABLE;

        /*
         * If filehandle is set with O_NONBLOCK, then must call select() here.
         *
         * The "selectable" field should be set false for those file handles
         * which the underlying OS does not support select() on.
         *
         * Note that a timeout will not work unless selectable is true.
         */
        if (impl->selectable)
        {
            return_code = OS_SelectSingle_Impl(token, &operation, abs_timeout);
        }

        if (return_code == OS_SUCCESS && (operation & OS_STREAM_STATE_READABLE) != 0)
        {
            os_result = read(impl->fd, buffer, nbytes);
            if (os_result < 0)
            {
                OS_DEBUG("read: %s\n", strerror(errno));
                return_code = OS_ERROR;
            }
            else
            {
                /* type conversion from ssize_t to int32 for return */
                return_code = (int32)os_result;
            }
        }
    }

    return return_code;
}

int32 OS_GenericSeek_Impl(const OS_object_token_t *token, osal_offset_t offset, uint32 whence)
{
    int                             where;
    off_t                           os_result;
    int32                           retval;
    OS_impl_file_internal_record_t *impl;

    impl = OS_OBJECT_TABLE_GET(OS_impl_filehandle_table, *token);

    switch (whence)
    {
        case OS_SEEK_SET:
            where = SEEK_SET;
            break;
        case OS_SEEK_CUR:
            where = SEEK_CUR;
            break;
        case OS_SEEK_END:
            where = SEEK_END;
            break;
        default:
            return OS_ERROR;
    }

    os_result = lseek(impl->fd, (off_t)offset, where);
    if (os_result == (off_t)-1)
    {
        if (errno == ESPIPE)
        {
            /*
             * this means the user tried to seek on a pipe, socket,
             * or other fifo-like handle that doesn't support seeking.
             *
             * Use a different error code to differentiate from an
             * error involving a bad whence/offset
             */
            retval = OS_ERR_OPERATION_NOT_SUPPORTED;
        }
        else
        {
            /*
             * Most likely the "whence" and/or "offset" combo was not valid.
             */
            OS_DEBUG("lseek: %s\n", strerror(errno));
            retval = OS_ERROR;
        }
    }
    else
    {
        /*
         * convert value to int32 type for returning to caller.
         * Note that this could potentially overflow an int32
         * for a large file seek.
         */
        retval = (int32)os_result;
    }

    return retval;
}

int32 OS_GenericSymbolLookup_Impl(SYMTAB_ID SymTab, cpuaddr *SymbolAddress, const char *SymbolName)
{
    STATUS      vxStatus;
    SYMBOL_DESC SymDesc;

    /*
    ** Check parameters
    */
    if ((SymbolAddress == NULL) || (SymbolName == NULL))
    {
        return OS_INVALID_POINTER;
    }

    /*
    ** Lookup the entry point
    **
    ** VxWorks 6.9 has deprecated the "symFindByName" API and it is replaced
    ** with a "symFind" API instead.
    */

    memset(&SymDesc, 0, sizeof(SYMBOL_DESC));
    SymDesc.mask = SYM_FIND_BY_NAME;
    SymDesc.name = (char *)SymbolName;

    vxStatus       = symFind(SymTab, &SymDesc);
    *SymbolAddress = (cpuaddr)SymDesc.value;

    if (vxStatus == ERROR)
    {
        return OS_ERROR;
    }

    return OS_SUCCESS;
}

int32 OS_GenericWrite_Impl(const OS_object_token_t *token, const void *buffer, size_t nbytes, OS_time_t abs_timeout)
{
    int32                           return_code;
    ssize_t                         os_result;
    uint32                          operation;
    OS_impl_file_internal_record_t *impl;

    impl = OS_OBJECT_TABLE_GET(OS_impl_filehandle_table, *token);

    return_code = OS_SUCCESS;

    if (nbytes > 0)
    {
        operation = OS_STREAM_STATE_WRITABLE;

        /*
         * If filehandle is set with O_NONBLOCK, then must call select() here.
         *
         * The "selectable" field should be set false for those file handles
         * which the underlying OS does not support select() on.
         *
         * Note that a timeout will not work unless selectable is true.
         */
        if (impl->selectable)
        {
            return_code = OS_SelectSingle_Impl(token, &operation, abs_timeout);
        }

        if (return_code == OS_SUCCESS && (operation & OS_STREAM_STATE_WRITABLE) != 0)
        {
            /* on some system libraries for which the write() argument is not
             * qualified correctly, it needs to be case to a void* here */
            os_result = write(impl->fd, GENERIC_IO_CONST_DATA_CAST buffer, nbytes);
            if (os_result < 0)
            {
                OS_DEBUG("write: %s\n", strerror(errno));
                return_code = OS_ERROR;
            }
            else
            {
                /* type conversion from ssize_t to int32 for return */
                return_code = (int32)os_result;
            }
        }
    }

    return return_code;
}

