int32 OS_QueueCreate(osal_id_t        *queue_id,
                     const char       *queue_name,
                     osal_blockcount_t queue_depth,
                     size_t            data_size,
                     uint32            flags)
{
    int32                       return_code;
    OS_object_token_t           token;
    OS_queue_internal_record_t *queue;

    /* validate inputs */
    OS_CHECK_POINTER(queue_id);
    OS_CHECK_APINAME(queue_name);
    OS_CHECK_SIZE(data_size);
    ARGCHECK(queue_depth <= OS_QUEUE_MAX_DEPTH, OS_QUEUE_INVALID_SIZE);

    /* Note - the common ObjectIdAllocate routine will lock the object type and leave it locked. */
    return_code = OS_ObjectIdAllocateNew(LOCAL_OBJID_TYPE, queue_name, &token);
    if (return_code == OS_SUCCESS)
    {
        queue = OS_OBJECT_TABLE_GET(OS_queue_table, token);

        /* Reset the table entry and save the name */
        OS_OBJECT_INIT(token, queue, queue_name, queue_name);

        queue->max_depth = queue_depth;
        queue->max_size  = data_size;

        /* Now call the OS-specific implementation.  This reads info from the queue table. */
        return_code = OS_QueueCreate_Impl(&token, flags);

        /* Check result, finalize record, and unlock global table. */
        return_code = OS_ObjectIdFinalizeNew(return_code, &token, queue_id);
    }

    return return_code;
}

int32 OS_QueueCreate_Impl(const OS_object_token_t *token, uint32 flags)
{
    MSG_Q_ID                         tmp_msgq_id;
    int                              queue_depth;
    int                              data_size;
    OS_impl_queue_internal_record_t *impl;
    OS_queue_internal_record_t      *queue;

    impl  = OS_OBJECT_TABLE_GET(OS_impl_queue_table, *token);
    queue = OS_OBJECT_TABLE_GET(OS_queue_table, *token);

    queue_depth = queue->max_depth; /* maximum number of messages in queue (queue depth) */
    data_size   = queue->max_size;  /* maximum size in bytes of a message */

    /* Create VxWorks Message Queue */
    tmp_msgq_id = msgQCreate(queue_depth, data_size, MSG_Q_FIFO);

    /* check if message Q create failed */
    if (tmp_msgq_id == 0)
    {
        OS_DEBUG("msgQCreate() - vxWorks errno %d\n", errno);
        return OS_ERROR;
    }

    impl->vxid = tmp_msgq_id;
    return OS_SUCCESS;
}

int32 OS_QueueDelete(osal_id_t queue_id)
