int32 OS_RwLockReadGive(osal_id_t rw_id)
{
    OS_rwlock_internal_record_t *rwlock;
    OS_object_token_t            token;
    int32                        return_code;

    /* Check Parameters */
    return_code = OS_ObjectIdGetById(OS_LOCK_MODE_NONE, LOCAL_OBJID_TYPE, rw_id, &token);
    if (return_code == OS_SUCCESS)
    {
        rwlock = OS_OBJECT_TABLE_GET(OS_rwlock_table, token);

        /* Ensure no write locks were held while this read lock was held */
        if (!OS_ObjectIdEqual(rwlock->last_writer, OS_OBJECT_ID_UNDEFINED))
        {
            OS_DEBUG("WARNING: Task %lu giving read lock on rwlock %lu while write lock held by task %lu\n",
                     OS_ObjectIdToInteger(OS_TaskGetId()),
                     OS_ObjectIdToInteger(rw_id),
                     OS_ObjectIdToInteger(rwlock->last_writer));
        }

        return_code = OS_RwLockReadGive_Impl(&token);
    }

    return return_code;
}

int32 OS_RwLockReadTake(osal_id_t rw_id)
{
    OS_rwlock_internal_record_t *rwlock;
    OS_object_token_t            token;
    int32                        return_code;

    /* Check Parameters */
    return_code = OS_ObjectIdGetById(OS_LOCK_MODE_NONE, LOCAL_OBJID_TYPE, rw_id, &token);
    if (return_code == OS_SUCCESS)
    {
        rwlock = OS_OBJECT_TABLE_GET(OS_rwlock_table, token);

        return_code = OS_RwLockReadTake_Impl(&token);

        /* Ensure no write locks are being held */
        if (return_code == OS_SUCCESS && !OS_ObjectIdEqual(rwlock->last_writer, OS_OBJECT_ID_UNDEFINED))
        {
            OS_DEBUG("WARNING: Task %lu taking read lock on rwlock %lu while write lock held by task %lu\n",
                     OS_ObjectIdToInteger(OS_TaskGetId()),
                     OS_ObjectIdToInteger(rw_id),
                     OS_ObjectIdToInteger(rwlock->last_writer));
        }
    }

    return return_code;
}

int32 OS_RwLockWriteGive(osal_id_t rw_id)
{
    OS_rwlock_internal_record_t *rwlock;
    OS_object_token_t            token;
    int32                        return_code;
    osal_id_t                    self_task;

    /* Check Parameters */
    return_code = OS_ObjectIdGetById(OS_LOCK_MODE_NONE, LOCAL_OBJID_TYPE, rw_id, &token);
    if (return_code == OS_SUCCESS)
    {
        rwlock = OS_OBJECT_TABLE_GET(OS_rwlock_table, token);

        self_task = OS_TaskGetId();

        /* Ensure multiple write locks weren't held */
        if (!OS_ObjectIdEqual(rwlock->last_writer, self_task))
        {
            OS_DEBUG("WARNING: Task %lu giving write lock on rwlock %lu while write lock held by task %lu\n",
                     OS_ObjectIdToInteger(self_task),
                     OS_ObjectIdToInteger(rw_id),
                     OS_ObjectIdToInteger(rwlock->last_writer));
        }

        rwlock->last_writer = OS_OBJECT_ID_UNDEFINED;

        return_code = OS_RwLockWriteGive_Impl(&token);
    }

    return return_code;
}

int32 OS_RwLockWriteTake(osal_id_t rw_id)
{
    OS_rwlock_internal_record_t *rwlock;
    OS_object_token_t            token;
    int32                        return_code;

    /* Check Parameters */
    return_code = OS_ObjectIdGetById(OS_LOCK_MODE_NONE, LOCAL_OBJID_TYPE, rw_id, &token);
    if (return_code == OS_SUCCESS)
    {
        rwlock = OS_OBJECT_TABLE_GET(OS_rwlock_table, token);

        return_code = OS_RwLockWriteTake_Impl(&token);
        if (return_code == OS_SUCCESS)
        {
            rwlock->last_writer = OS_TaskGetId();
        }
    }

    return return_code;
}

int32 OS_SelectFdAdd(OS_FdSet *Set, osal_id_t objid)
{
    int32        return_code;
    osal_index_t local_id;

    /* check parameters */
    OS_CHECK_POINTER(Set);

    return_code = OS_ObjectIdToArrayIndex(OS_OBJECT_TYPE_OS_STREAM, objid, &local_id);
    if (return_code == OS_SUCCESS)
    {
        /*
         * Sets the bit in the uint8 object_ids array that corresponds
         * to the local_id where local_id >> 3 determines the array element,
         * and the mask/shift sets the bit within that element.
         */
        Set->object_ids[local_id >> 3] |= 1 << (local_id & 0x7);
    }

    return return_code;
}

int32 OS_SelectFdClear(OS_FdSet *Set, osal_id_t objid)
{
    int32        return_code;
    osal_index_t local_id;

    /* check parameters */
    OS_CHECK_POINTER(Set);

    return_code = OS_ObjectIdToArrayIndex(OS_OBJECT_TYPE_OS_STREAM, objid, &local_id);
    if (return_code == OS_SUCCESS)
    {
        /*
         * Clears the bit in the uint8 object_ids array that corresponds
         * to the local_id where local_id >> 3 determines the array element,
         * and the mask/shift clears the bit within that element.
         */
        Set->object_ids[local_id >> 3] &= ~(1 << (local_id & 0x7));
    }

    return return_code;
}

bool OS_SelectFdIsSet(const OS_FdSet *Set, osal_id_t objid)
{
    int32        return_code;
    osal_index_t local_id;

    /* check parameters */
    BUGCHECK(Set != NULL, false);

    return_code = OS_ObjectIdToArrayIndex(OS_OBJECT_TYPE_OS_STREAM, objid, &local_id);
    if (return_code != OS_SUCCESS)
    {
        return false;
    }

    /*
     * Returns boolean for if the bit in the uint8 object_ids array that corresponds
     * to the local_id is set where local_id >> 3 determines the array element,
     * and the mask/shift checks the bit within that element.
     */
    return ((Set->object_ids[local_id >> 3] >> (local_id & 0x7)) & 0x1);
}

int32 OS_SelectFdZero(OS_FdSet *Set)
{
    /* check parameters */
    OS_CHECK_POINTER(Set);

    memset(Set, 0, sizeof(OS_FdSet));
    return OS_SUCCESS;
}

