    return OS_SelectMultipleAbs(ReadSet, WriteSet, OS_TimeFromRelativeMilliseconds(msecs));
}

int32 OS_SelectMultipleAbs(OS_FdSet *ReadSet, OS_FdSet *WriteSet, OS_time_t abs_timeout)
{
    int32 return_code;

    /*
     * Check parameters
     *
     * Note "ReadSet" and "WriteSet" are not checked, because in certain configurations they can be validly null.
     */

    /*
     * This does not currently increment any refcounts.
     * That means a file/socket can be closed while actively inside a
     * OS_SelectMultiple() call in another thread.
     */
    return_code = OS_SelectMultiple_Impl(ReadSet, WriteSet, abs_timeout);

    return return_code;
}

int32 OS_SelectMultiple_Impl(OS_FdSet *ReadSet, OS_FdSet *WriteSet, OS_time_t abs_timeout)
{
    fd_set wr_set;
    fd_set rd_set;
    int    maxfd;
    int32  return_code;

    FD_ZERO(&rd_set);
    FD_ZERO(&wr_set);
    maxfd = -1;
    if (ReadSet != NULL)
    {
        return_code = OS_FdSet_ConvertIn_Impl(&maxfd, &rd_set, ReadSet);
        if (return_code != OS_SUCCESS)
        {
            return return_code;
        }
    }
    if (WriteSet != NULL)
    {
        return_code = OS_FdSet_ConvertIn_Impl(&maxfd, &wr_set, WriteSet);
        if (return_code != OS_SUCCESS)
        {
            return return_code;
        }
    }

    if (maxfd >= 0)
    {
        return_code = OS_DoSelect(maxfd, &rd_set, &wr_set, abs_timeout);
    }
    else
    {
        /*
         * This return code will be used if the set(s) were
         * both empty/NULL or otherwise did not contain valid filehandles.
         */
        return_code = OS_ERR_INVALID_ID;
    }

    if (return_code == OS_SUCCESS)
    {
        if (ReadSet != NULL)
        {
            OS_FdSet_ConvertOut_Impl(&rd_set, ReadSet);
        }
        if (WriteSet != NULL)
        {
            OS_FdSet_ConvertOut_Impl(&wr_set, WriteSet);
        }
    }

    return return_code;
}

int32 OS_SelectSingle(osal_id_t objid, uint32 *StateFlags, int32 msecs)
{
    return OS_SelectSingleAbs(objid, StateFlags, OS_TimeFromRelativeMilliseconds(msecs));
}

int32 OS_SelectSingleAbs(osal_id_t objid, uint32 *StateFlags, OS_time_t abs_timeout)
{
    int32             return_code;
    OS_object_token_t token;

    /* check parameters */
    OS_CHECK_POINTER(StateFlags);

    return_code = OS_ObjectIdGetById(OS_LOCK_MODE_REFCOUNT, OS_OBJECT_TYPE_OS_STREAM, objid, &token);
    if (return_code == OS_SUCCESS)
    {
        return_code = OS_SelectSingle_Impl(&token, StateFlags, abs_timeout);

        OS_ObjectIdRelease(&token);
    }

    return return_code;
}

int32 OS_SelectSingle_Impl(const OS_object_token_t *token, uint32 *SelectFlags, OS_time_t abs_timeout)
{
    int32                           return_code;
    fd_set                          wr_set;
    fd_set                          rd_set;
    OS_impl_file_internal_record_t *impl;

    impl = OS_OBJECT_TABLE_GET(OS_impl_filehandle_table, *token);

    /*
     * If called on a stream_id which does not support this
     * operation, return immediately and do not invoke the system call
     */
    if (!impl->selectable)
    {
        return OS_ERR_OPERATION_NOT_SUPPORTED;
    }

    if (impl->fd >= FD_SETSIZE)
    {
        /* out of range of select() implementation */
        return OS_ERR_OPERATION_NOT_SUPPORTED;
    }

    if (*SelectFlags != 0)
    {
        FD_ZERO(&wr_set);
        FD_ZERO(&rd_set);
        if (*SelectFlags & OS_STREAM_STATE_READABLE)
        {
            FD_SET(impl->fd, &rd_set);
        }
        if (*SelectFlags & OS_STREAM_STATE_WRITABLE)
        {
            FD_SET(impl->fd, &wr_set);
        }

        return_code = OS_DoSelect(impl->fd, &rd_set, &wr_set, abs_timeout);

        if (return_code == OS_SUCCESS)
        {
            if (!FD_ISSET(impl->fd, &rd_set))
            {
                *SelectFlags &= ~OS_STREAM_STATE_READABLE;
            }
            if (!FD_ISSET(impl->fd, &wr_set))
            {
                *SelectFlags &= ~OS_STREAM_STATE_WRITABLE;
            }
        }
        else
        {
            *SelectFlags = 0;
        }
    }
    else
    {
        /* Nothing to check for, return immediately. */
        return_code = OS_SUCCESS;
    }

    return return_code;
}

