int32 OS_SocketBind(osal_id_t sock_id, const OS_SockAddr_t *Addr)
{
    int32 return_code;

    return_code = OS_SocketBindAddress(sock_id, Addr);
    if (return_code == OS_SUCCESS)
    {
        return_code = OS_SocketListen(sock_id);
        if (return_code == OS_ERR_INCORRECT_OBJ_TYPE)
        {
            /* This one is OK, it happens if the socket is a datagram/connectionless
             * type that does not need to listen().  For backward compatibility, report
             * success to the caller.
             */
            return_code = OS_SUCCESS;
        }
    }

    return return_code;
}

int32 OS_SocketBindAddress(osal_id_t sock_id, const OS_SockAddr_t *Addr)
{
    OS_common_record_t          *record;
    OS_stream_internal_record_t *stream;
    OS_object_token_t            token;
    int32                        return_code;

    /* Check Parameters */
    OS_CHECK_POINTER(Addr);

    return_code = OS_ObjectIdGetById(OS_LOCK_MODE_EXCLUSIVE, LOCAL_OBJID_TYPE, sock_id, &token);
    if (return_code == OS_SUCCESS)
    {
        record = OS_OBJECT_TABLE_GET(OS_global_stream_table, token);
        stream = OS_OBJECT_TABLE_GET(OS_stream_table, token);

        if (stream->socket_domain == OS_SocketDomain_INVALID)
        {
            /* Not a socket */
            return_code = OS_ERR_INCORRECT_OBJ_TYPE;
        }
        else if ((stream->stream_state & (OS_STREAM_STATE_BOUND | OS_STREAM_STATE_CONNECTED)) != 0)
        {
            /* Socket must be neither bound nor connected */
            return_code = OS_ERR_INCORRECT_OBJ_STATE;
        }
        else
        {
            return_code = OS_SocketBindAddress_Impl(&token, Addr);

            if (return_code == OS_SUCCESS)
            {
                OS_CreateSocketName(&token, Addr, NULL);
                record->name_entry    = stream->stream_name;
                stream->stream_state |= OS_STREAM_STATE_BOUND;
            }
        }

        OS_ObjectIdRelease(&token);
    }

    return return_code;
}

int32 OS_SocketBindAddress_Impl(const OS_object_token_t *token, const OS_SockAddr_t *Addr)
{
    int                             os_result;
    socklen_t                       addrlen;
    const struct sockaddr          *sa;
    OS_impl_file_internal_record_t *impl;

    impl = OS_OBJECT_TABLE_GET(OS_impl_filehandle_table, *token);

    sa = (const struct sockaddr *)&Addr->AddrData;

    switch (sa->sa_family)
    {
        case AF_INET:
            addrlen = sizeof(struct sockaddr_in);
            break;
#ifdef OS_NETWORK_SUPPORTS_IPV6
        case AF_INET6:
            addrlen = sizeof(struct sockaddr_in6);
            break;
#endif
        default:
            addrlen = 0;
            break;
    }

    if (addrlen == 0)
    {
        return OS_ERR_BAD_ADDRESS;
    }

    os_result = bind(impl->fd, sa, addrlen);
    if (os_result < 0)
    {
        OS_DEBUG("bind: %s\n", strerror(errno));
        return OS_ERROR;
    }

    return OS_SUCCESS;
}

int32 OS_SocketConnect(osal_id_t sock_id, const OS_SockAddr_t *Addr, int32 timeout)
{
    return OS_SocketConnectAbs(sock_id, Addr, OS_TimeFromRelativeMilliseconds(timeout));
}

int32 OS_SocketConnectAbs(osal_id_t sock_id, const OS_SockAddr_t *Addr, OS_time_t abs_timeout)
{
    OS_stream_internal_record_t *stream;
    OS_object_token_t            token;
    int32                        return_code;

    /* Check Parameters */
    OS_CHECK_POINTER(Addr);

    return_code = OS_ObjectIdGetById(OS_LOCK_MODE_EXCLUSIVE, LOCAL_OBJID_TYPE, sock_id, &token);
    if (return_code == OS_SUCCESS)
    {
        stream = OS_OBJECT_TABLE_GET(OS_stream_table, token);

        if (stream->socket_domain == OS_SocketDomain_INVALID)
        {
            return_code = OS_ERR_INCORRECT_OBJ_TYPE;
        }
        else if (stream->socket_type == OS_SocketType_STREAM && (stream->stream_state & OS_STREAM_STATE_CONNECTED) != 0)
        {
            /* Stream socket must not be connected */
            return_code = OS_ERR_INCORRECT_OBJ_STATE;
        }
        else
        {
            return_code = OS_SocketConnect_Impl(&token, Addr, abs_timeout);

            if (return_code == OS_SUCCESS)
            {
                stream->stream_state |= OS_STREAM_STATE_CONNECTED | OS_STREAM_STATE_READABLE | OS_STREAM_STATE_WRITABLE;
            }
        }

        OS_ObjectIdRelease(&token);
    }

    return return_code;
}

int32 OS_SocketConnect_Impl(const OS_object_token_t *token, const OS_SockAddr_t *Addr, OS_time_t abs_timeout)
{
    int32                           return_code;
    int                             os_status;
    int                             sockopt;
    socklen_t                       slen;
    uint32                          operation;
    const struct sockaddr          *sa;
    OS_impl_file_internal_record_t *impl;

    impl = OS_OBJECT_TABLE_GET(OS_impl_filehandle_table, *token);

    sa = (const struct sockaddr *)&Addr->AddrData;
    switch (sa->sa_family)
    {
        case AF_INET:
            slen = sizeof(struct sockaddr_in);
            break;
#ifdef OS_NETWORK_SUPPORTS_IPV6
        case AF_INET6:
            slen = sizeof(struct sockaddr_in6);
            break;
#endif
        default:
            slen = 0;
            break;
    }

    if (slen != Addr->ActualLength)
    {
        return_code = OS_ERR_BAD_ADDRESS;
    }
    else
    {
        return_code = OS_SUCCESS;
        os_status   = connect(impl->fd, sa, slen);
        if (os_status < 0)
        {
            if (errno != EINPROGRESS)
            {
                OS_DEBUG("connect: %s\n", strerror(errno));
                return_code = OS_ERROR;
            }
            else
            {
                /*
                 * If the socket was created in nonblocking mode (O_NONBLOCK flag) then the connect
                 * runs in the background and connect() returns EINPROGRESS.  In this case we still
                 * want to provide the "normal" (blocking) semantics to the calling app, such that
                 * when OS_SocketConnect() returns, the socket is ready for use.
                 *
                 * To provide consistent behavior to calling apps, this does a select() to wait
                 * for the socket to become writable, meaning that the remote side is connected.
                 *
                 * An important point here is that the calling app can control the timeout.  If the
                 * normal/blocking connect() was used, the OS/IP stack controls the timeout, and it
                 * can be quite long.
                 */
                operation = OS_STREAM_STATE_WRITABLE;
                if (impl->selectable)
                {
                    return_code = OS_SelectSingle_Impl(token, &operation, abs_timeout);
                }
                if (return_code == OS_SUCCESS)
                {
                    if ((operation & OS_STREAM_STATE_WRITABLE) == 0)
                    {
                        return_code = OS_ERROR_TIMEOUT;
                    }
                    else
                    {
                        /*
                         * The SO_ERROR socket flag should also read back zero.
                         * If not zero, something went wrong during connect
                         */
                        sockopt   = 0;
                        slen      = sizeof(sockopt);
                        os_status = getsockopt(impl->fd, SOL_SOCKET, SO_ERROR, &sockopt, &slen);
                        if (os_status < 0 || sockopt != 0)
                        {
                            return_code = OS_ERROR;
                        }
                    }
                }
            }
        }
    }
    return return_code;
}

int32 OS_SocketGetDSCP_Impl(const OS_object_token_t *token, OS_socket_optval_t *optval)
{
    OS_impl_file_internal_record_t *impl;
    int                             os_flags;
    socklen_t                       optlen;

    /* The DSCP value lives in the upper 6 bits of the IPv4 ToS field */
    impl = OS_OBJECT_TABLE_GET(OS_impl_filehandle_table, *token);

    optlen = sizeof(os_flags);
    if (getsockopt(impl->fd, IPPROTO_IP, IP_TOS, &os_flags, &optlen) < 0)
    {
        /* No recourse if getsockopt() fails - just report the error and move on. */
        OS_DEBUG("getsockopt(IP_TOS): %s\n", strerror(errno));
        return OS_ERROR;
    }

    optval->IntVal = (os_flags >> 2) & 0x3F;

    return OS_SUCCESS;
}

