int32 OS_SocketListen(osal_id_t sock_id)
{
    OS_stream_internal_record_t *stream;
    OS_object_token_t            token;
    int32                        return_code;

    return_code = OS_ObjectIdGetById(OS_LOCK_MODE_EXCLUSIVE, LOCAL_OBJID_TYPE, sock_id, &token);
    if (return_code == OS_SUCCESS)
    {
        stream = OS_OBJECT_TABLE_GET(OS_stream_table, token);

        /* This call is only applicable to stream sockets */
        if (stream->socket_domain == OS_SocketDomain_INVALID || stream->socket_type != OS_SocketType_STREAM)
        {
            /* Not a stream socket */
            return_code = OS_ERR_INCORRECT_OBJ_TYPE;
        }
        else if ((stream->stream_state & OS_STREAM_STATE_BOUND) == 0)
        {
            /* Socket must be bound to an address already */
            return_code = OS_ERR_INCORRECT_OBJ_STATE;
        }
        else if ((stream->stream_state & (OS_STREAM_STATE_LISTENING | OS_STREAM_STATE_CONNECTED)) != 0)
        {
            /* Socket must be neither listening nor connected */
            return_code = OS_ERR_INCORRECT_OBJ_STATE;
        }
        else
        {
            return_code = OS_SocketListen_Impl(&token);

            if (return_code == OS_SUCCESS)
            {
                stream->stream_state |= OS_STREAM_STATE_LISTENING;
            }
        }

        OS_ObjectIdRelease(&token);
    }

    return return_code;
}

int32 OS_SocketListen_Impl(const OS_object_token_t *token)
{
    int                             os_result;
    OS_impl_file_internal_record_t *impl;

    impl = OS_OBJECT_TABLE_GET(OS_impl_filehandle_table, *token);

    os_result = listen(impl->fd, 10);
    if (os_result < 0)
    {
        OS_DEBUG("listen: %s\n", strerror(errno));
        return OS_ERROR;
    }

    return OS_SUCCESS;
}

int32 OS_SocketOpen(osal_id_t *sock_id, OS_SocketDomain_t Domain, OS_SocketType_t Type)
{
    OS_object_token_t            token;
    OS_stream_internal_record_t *stream;
    int32                        return_code;

    /* Check for NULL pointers */
    OS_CHECK_POINTER(sock_id);

    /* Note - the common ObjectIdAllocate routine will lock the object type and leave it locked. */
    return_code = OS_ObjectIdAllocateNew(LOCAL_OBJID_TYPE, NULL, &token);
    if (return_code == OS_SUCCESS)
    {
        stream = OS_OBJECT_TABLE_GET(OS_stream_table, token);

        /* Save all the data to our own internal table */
        memset(stream, 0, sizeof(OS_stream_internal_record_t));
        stream->socket_domain = Domain;
        stream->socket_type   = Type;

        /* Now call the OS-specific implementation.  This reads info from the table. */
        return_code = OS_SocketOpen_Impl(&token);

        /* Check result, finalize record, and unlock global table. */
        return_code = OS_ObjectIdFinalizeNew(return_code, &token, sock_id);
    }

    return return_code;
}

int32 OS_SocketOpen_Impl(const OS_object_token_t *token)
{
    int                             os_domain;
    int                             os_type;
    int                             os_proto;
    int                             os_flags;
    OS_impl_file_internal_record_t *impl;
    OS_stream_internal_record_t    *stream;

    impl   = OS_OBJECT_TABLE_GET(OS_impl_filehandle_table, *token);
    stream = OS_OBJECT_TABLE_GET(OS_stream_table, *token);

    os_proto = 0;

    switch (stream->socket_type)
    {
        case OS_SocketType_DATAGRAM:
            os_type  = SOCK_DGRAM;
            os_proto = IPPROTO_UDP;
            break;

        case OS_SocketType_STREAM:
            os_type  = SOCK_STREAM;
            os_proto = IPPROTO_TCP;
            break;

        default:
            return OS_ERR_NOT_IMPLEMENTED;
    }

    switch (stream->socket_domain)
    {
        case OS_SocketDomain_INET:
            os_domain = AF_INET;
            break;
#ifdef OS_NETWORK_SUPPORTS_IPV6
        case OS_SocketDomain_INET6:
            os_domain = AF_INET6;
            break;
#endif
        default:
            return OS_ERR_NOT_IMPLEMENTED;
    }

    impl->fd = socket(os_domain, os_type, os_proto);
    if (impl->fd < 0)
    {
        return OS_ERROR;
    }

    /*
     * Setting the REUSEADDR flag helps during debugging when there might be frequent
     * code restarts.  However if setting the option fails then it is not worth bailing out over.
     */
    os_flags = 1;
    setsockopt(impl->fd, SOL_SOCKET, SO_REUSEADDR, &os_flags, sizeof(os_flags));

    /*
     * Set the standard options on the filehandle by default --
     * this may set it to non-blocking mode if the implementation supports it.
     * any blocking would be done explicitly via the select() wrappers
     *
     * NOTE: The implementation still generally works without this flag set, but
     * nonblock mode does improve robustness in the event that multiple tasks
     * attempt to accept new connections from the same server socket at the same time.
     */
    OS_IMPL_SET_SOCKET_FLAGS(token);

    return OS_SUCCESS;
}

int32 OS_SocketRecvFrom(osal_id_t sock_id, void *buffer, size_t buflen, OS_SockAddr_t *RemoteAddr, int32 timeout)
{
