}

int32 OS_SocketRecvFromAbs(osal_id_t      sock_id,
                           void          *buffer,
                           size_t         buflen,
                           OS_SockAddr_t *RemoteAddr,
                           OS_time_t      abs_timeout)
{
    OS_stream_internal_record_t *stream;
    OS_object_token_t            token;
    int32                        return_code;

    /*
     * Check parameters
     *
     * Note "RemoteAddr" is not checked, because in certain configurations it can be validly null.
     */
    OS_CHECK_POINTER(buffer);
    OS_CHECK_SIZE(buflen);

    return_code = OS_ObjectIdGetById(OS_LOCK_MODE_REFCOUNT, LOCAL_OBJID_TYPE, sock_id, &token);
    if (return_code == OS_SUCCESS)
    {
        stream = OS_OBJECT_TABLE_GET(OS_stream_table, token);

        if (stream->socket_type != OS_SocketType_DATAGRAM)
        {
            return_code = OS_ERR_INCORRECT_OBJ_TYPE;
        }
        else if ((stream->stream_state & OS_STREAM_STATE_BOUND) == 0)
        {
            /* Socket needs to be bound first */
            return_code = OS_ERR_INCORRECT_OBJ_STATE;
        }
        else
        {
            return_code = OS_SocketRecvFrom_Impl(&token, buffer, buflen, RemoteAddr, abs_timeout);
        }

        OS_ObjectIdRelease(&token);
    }

    return return_code;
}

int32 OS_SocketRecvFrom_Impl(const OS_object_token_t *token,
                             void                    *buffer,
                             size_t                   buflen,
                             OS_SockAddr_t           *RemoteAddr,
                             OS_time_t                abs_timeout)
{
    int32                           return_code;
    int                             os_result;
    int                             waitflags;
    uint32                          operation;
    struct sockaddr                *sa;
    socklen_t                       addrlen;
    OS_impl_file_internal_record_t *impl;

    impl = OS_OBJECT_TABLE_GET(OS_impl_filehandle_table, *token);

    if (RemoteAddr == NULL)
    {
        sa      = NULL;
        addrlen = 0;
    }
    else
    {
        addrlen = OS_SOCKADDR_MAX_LEN;
        sa      = (struct sockaddr *)&RemoteAddr->AddrData;
    }

    operation = OS_STREAM_STATE_READABLE;
    /*
     * If "O_NONBLOCK" flag is set then use select()
     * Note this is the only way to get a correct timeout
     */
    if (impl->selectable)
    {
        waitflags   = MSG_DONTWAIT;
        return_code = OS_SelectSingle_Impl(token, &operation, abs_timeout);
    }
    else
    {
        /* This is a backup option - check if the abs timeout would be a poll/check op */
        if (OS_TimeToRelativeMilliseconds(abs_timeout) == OS_CHECK)
        {
            waitflags = MSG_DONTWAIT;
        }
        else
        {
            /* note timeout will not be honored if >0 */
            waitflags = 0;
        }
        return_code = OS_SUCCESS;
    }

    if (return_code == OS_SUCCESS)
    {
        if ((operation & OS_STREAM_STATE_READABLE) == 0)
        {
            return_code = OS_ERROR_TIMEOUT;
        }
        else
        {
            os_result = recvfrom(impl->fd, buffer, buflen, waitflags, sa, &addrlen);
            if (os_result < 0)
            {
                if (errno == EAGAIN || errno == EWOULDBLOCK)
                {
                    return_code = OS_QUEUE_EMPTY;
                }
                else
                {
                    OS_DEBUG("recvfrom: %s\n", strerror(errno));
                    return_code = OS_ERROR;
                }
            }
            else
            {
                return_code = os_result;

                if (RemoteAddr != NULL)
                {
                    RemoteAddr->ActualLength = addrlen;
                }
            }
        }
    }

    return return_code;
}

int32 OS_SocketSendTo(osal_id_t sock_id, const void *buffer, size_t buflen, const OS_SockAddr_t *RemoteAddr)
{
    OS_stream_internal_record_t *stream;
