    OS_CHECK_POINTER(RemoteAddr);

    return_code = OS_ObjectIdGetById(OS_LOCK_MODE_REFCOUNT, LOCAL_OBJID_TYPE, sock_id, &token);
    if (return_code == OS_SUCCESS)
    {
        stream = OS_OBJECT_TABLE_GET(OS_stream_table, token);

        if (stream->socket_type != OS_SocketType_DATAGRAM)
        {
            return_code = OS_ERR_INCORRECT_OBJ_TYPE;
        }
        else
        {
            return_code = OS_SocketSendTo_Impl(&token, buffer, buflen, RemoteAddr);
        }

        OS_ObjectIdRelease(&token);
    }

    return return_code;
}

int32 OS_SocketSendTo_Impl(const OS_object_token_t *token,
                           const void              *buffer,
                           size_t                   buflen,
                           const OS_SockAddr_t     *RemoteAddr)
{
    int                             os_result;
    socklen_t                       addrlen;
    const struct sockaddr          *sa;
    OS_impl_file_internal_record_t *impl;

    impl = OS_OBJECT_TABLE_GET(OS_impl_filehandle_table, *token);

    sa = (const struct sockaddr *)&RemoteAddr->AddrData;
    switch (sa->sa_family)
    {
        case AF_INET:
            addrlen = sizeof(struct sockaddr_in);
            break;
#ifdef OS_NETWORK_SUPPORTS_IPV6
        case AF_INET6:
            addrlen = sizeof(struct sockaddr_in6);
            break;
#endif
        default:
            addrlen = 0;
            break;
    }

    if (addrlen != RemoteAddr->ActualLength)
    {
        return OS_ERR_BAD_ADDRESS;
    }

    os_result = sendto(impl->fd, buffer, buflen, MSG_DONTWAIT, sa, addrlen);
    if (os_result < 0)
    {
        OS_DEBUG("sendto: %s\n", strerror(errno));
        return OS_ERROR;
    }

    return os_result;
}

int32 OS_SocketSetDSCP_Impl(const OS_object_token_t *token, const OS_socket_optval_t *optval)
{
    OS_impl_file_internal_record_t *impl;
    int                             os_flags;
    socklen_t                       optlen;

    /* The DSCP value lives in the upper 6 bits of the IPv4 ToS field */
    impl = OS_OBJECT_TABLE_GET(OS_impl_filehandle_table, *token);

    /* Preserve the setting of the lower two bits (ECN) by reading ToS first */
    optlen = sizeof(os_flags);
    if (getsockopt(impl->fd, IPPROTO_IP, IP_TOS, &os_flags, &optlen) < 0)
    {
        /* No recourse if getsockopt() fails - just report the error and move on. */
        OS_DEBUG("getsockopt(IP_TOS): %s\n", strerror(errno));
        return OS_ERROR;
    }

    os_flags = (os_flags & 0x03) | ((optval->IntVal << 2) & 0xFC);

    if (setsockopt(impl->fd, IPPROTO_IP, IP_TOS, &os_flags, sizeof(os_flags)) < 0)
    {
        /* No recourse if setsockopt() fails - just report the error and move on. */
        OS_DEBUG("setsockopt(IP_TOS): %s\n", strerror(errno));
        return OS_ERROR;
    }

    return OS_SUCCESS;
}

