int32 OS_SocketShutdown(osal_id_t sock_id, OS_SocketShutdownMode_t Mode)
{
    OS_stream_internal_record_t *stream;
    OS_object_token_t            token;
    int32                        return_code;

    /* Confirm that "Mode" is one of the 3 acceptable values */
    BUGCHECK(Mode == OS_SocketShutdownMode_SHUT_READ || Mode == OS_SocketShutdownMode_SHUT_WRITE
                 || Mode == OS_SocketShutdownMode_SHUT_READWRITE,
             OS_ERR_INVALID_ARGUMENT);

    return_code = OS_ObjectIdGetById(OS_LOCK_MODE_GLOBAL, LOCAL_OBJID_TYPE, sock_id, &token);
    if (return_code == OS_SUCCESS)
    {
        stream = OS_OBJECT_TABLE_GET(OS_stream_table, token);

        if (stream->socket_domain == OS_SocketDomain_INVALID)
        {
            return_code = OS_ERR_INCORRECT_OBJ_TYPE;
        }
        else if (stream->socket_type == OS_SocketType_STREAM && (stream->stream_state & OS_STREAM_STATE_CONNECTED) == 0)
        {
            /* Stream socket must not be connected */
            return_code = OS_ERR_INCORRECT_OBJ_STATE;
        }
        else
        {
            return_code = OS_SocketShutdown_Impl(&token, Mode);

            if (return_code == OS_SUCCESS)
            {
                if (Mode & OS_SocketShutdownMode_SHUT_READ)
                {
                    stream->stream_state &= ~OS_STREAM_STATE_READABLE;
                }
                if (Mode & OS_SocketShutdownMode_SHUT_WRITE)
                {
                    stream->stream_state &= ~OS_STREAM_STATE_WRITABLE;
                }
            }
        }

        OS_ObjectIdRelease(&token);
    }

    return return_code;
}

int32 OS_SocketShutdown_Impl(const OS_object_token_t *token, OS_SocketShutdownMode_t Mode)
{
    OS_impl_file_internal_record_t *conn_impl;
    int32                           return_code;
    int                             how;

    conn_impl = OS_OBJECT_TABLE_GET(OS_impl_filehandle_table, *token);

    /* Note that when called via the shared layer,
     * the "Mode" arg has already been checked/validated. */
    if (Mode == OS_SocketShutdownMode_SHUT_READ)
    {
        how = SHUT_RD;
    }
    else if (Mode == OS_SocketShutdownMode_SHUT_WRITE)
    {
        how = SHUT_WR;
    }
    else
    {
        how = SHUT_RDWR;
    }

    if (shutdown(conn_impl->fd, how) == 0)
    {
        return_code = OS_SUCCESS;
    }
    else
    {
        return_code = OS_ERROR;
    }

    return return_code;
}

static inline long OS_StatusToInteger(osal_status_t Status)
{
    return (long)Status;
}

char *OS_StatusToString(osal_status_t status, os_status_string_t *status_string)
{
    char *string = NULL;

    if (status_string != NULL)
    {
        // SAD: No need to check snprintf return; OS_STATUS_STRING_LENGTH (12) is ample for all status values
        snprintf(*status_string, sizeof(*status_string), "%ld", OS_StatusToInteger(status));
        string = *status_string;
    }
    return string;
}

BOOL OS_SymTableIterator_Impl(char *name, SYM_VALUE val, SYM_TYPE type, _Vx_usr_arg_t arg, SYM_GROUP group)
{
    SymbolRecord_t     symRecord;
    size_t             NextSize;
    int                status;
    SymbolDumpState_t *state;

    /*
     * Rather than passing the state pointer through the generic "int" arg,
     * use a global.  This is OK because dumps are serialized externally.
     */
    state = &OS_VxWorks_SymbolDumpState;

    /*
    ** Copy symbol name
    */
    strncpy(symRecord.SymbolName, name, sizeof(symRecord.SymbolName) - 1);
    symRecord.SymbolName[sizeof(symRecord.SymbolName) - 1] = '\0';

    /*
    ** Check to see if the max length of each symbol name has been reached
    */
    if (memchr(name, 0, OS_MAX_SYM_LEN) == NULL)
    {
        symRecord.SymbolName[sizeof(symRecord.SymbolName) - 2] = '*';
        OS_DEBUG("%s(): symbol name too long\n", __func__);
    }

    /*
    ** Check to see if the maximum size of the file has been reached
    */
    NextSize = state->CurrSize + sizeof(symRecord);
    if (NextSize > state->Sizelimit)
    {
        /*
        ** We exceeded the maximum size, so tell vxWorks to stop
        ** However this is not considered an error, just a stop condition.
        */
        OS_DEBUG("%s(): symbol table size exceeded\n", __func__);
        state->StatusCode = OS_ERR_OUTPUT_TOO_LARGE;
        return false;
    }

    /*
    ** Save symbol address
    */
    symRecord.SymbolAddress = (cpuaddr)val;

    /*
    ** Write entry in file
    */
    status = write(state->fd, (char *)&symRecord, sizeof(symRecord));
    /* There is a problem if not all bytes were written OR if we get an error
     * value, < 0. */
    if (status < (int)sizeof(symRecord))
    {
        state->StatusCode = OS_ERROR;
        return false;
    }

    state->CurrSize = NextSize;

    /*
    ** It's OK to continue
    */
    return true;
}

int32 OS_SymbolLookup(cpuaddr *symbol_address, const char *SymbolName)
{
    int32 return_code;
    int32 staticsym_status;

    /*
    ** Check parameters
    */
    OS_CHECK_POINTER(symbol_address);
    OS_CHECK_POINTER(SymbolName);

    /*
     * attempt to find the symbol in the symbol table
     */
    return_code = OS_SymbolLookup_Impl(symbol_address, SymbolName);

    /*
     * If the OS call did not find the symbol or the loader is
     * disabled, then check if a static symbol table is present
     */
    if (return_code != OS_SUCCESS)
    {
        staticsym_status = OS_SymbolLookup_Static(symbol_address, SymbolName, NULL);

        /*
         * Only overwrite the return code if static lookup was successful.
         * Otherwise keep the error code from the low level implementation.
         */
        if (staticsym_status == OS_SUCCESS)
        {
            return_code = staticsym_status;
        }
    }

    return return_code;
}

int32 OS_SymbolLookup_Impl(cpuaddr *SymbolAddress, const char *SymbolName)
{
    return OS_GenericSymbolLookup_Impl(sysSymTbl, SymbolAddress, SymbolName);
}

int32 OS_SymbolLookup_Static(cpuaddr *SymbolAddress, const char *SymbolName, const char *ModuleName)
{
    int32                      return_code = OS_ERR_NOT_IMPLEMENTED;
    OS_static_symbol_record_t *StaticSym   = OS_STATIC_SYMTABLE_SOURCE;

    while (StaticSym != NULL)
    {
        if (StaticSym->Name == NULL)
        {
            /* end of list --
             * Return "OS_ERROR" to indicate that an actual search was done
             * with a not-found result, vs. not searching at all. */
            return_code = OS_ERROR;
            /* note: instead of including a regular break statement here, we
             * do this so that we can get full coverage on the MC/DC tests. The
             * two lines below in terms of behavior for this function are equivalent.
             * Because for coverage purposes we only need to execute each branch
             * and/or condition at least once, the other break statement in this
             * while loop is left as is, since the break statement is more clear
             * about what its purpose is rather than the two lines below. */
            StaticSym   = NULL;
            continue;
        }
        if (strcmp(StaticSym->Name, SymbolName) == 0
            && (ModuleName == NULL || strcmp(StaticSym->Module, ModuleName) == 0))
        {
            /* found matching symbol */
            *SymbolAddress = (cpuaddr)StaticSym->Address;
            return_code    = OS_SUCCESS;
            break;
        }

        ++StaticSym;
    }

    return return_code;
}

int32 OS_SymbolTableDump(const char *filename, size_t size_limit)
{
    int32             return_code;
    char              translated_path[OS_MAX_LOCAL_PATH_LEN];
    OS_object_token_t token;

    /* Check parameters */
    OS_CHECK_POINTER(filename);

    /*
     ** Translate the filename to the Host System
     */
    return_code = OS_TranslatePath(filename, translated_path);
    if (return_code != OS_SUCCESS)
    {
        return return_code;
    }

    /*
     * Locking the global ensures only one symbol table dump
     * can be executing.  It also prevents module loading/unloading
     * while the dump is occurring.
     *
     * Because calls to this function are serialized, the
     * underlying implementation may safely use globals for
     * state storage.
     */
    return_code = OS_ObjectIdTransactionInit(OS_LOCK_MODE_GLOBAL, LOCAL_OBJID_TYPE, &token);
    if (return_code != OS_SUCCESS)
    {
        return return_code;
    }

    return_code = OS_SymbolTableDump_Impl(translated_path, size_limit);

    OS_ObjectIdTransactionCancel(&token);

    return return_code;
}

int32 OS_SymbolTableDump_Impl(const char *filename, size_t size_limit)
{
    SymbolDumpState_t *state;

    /*
     * Rather than passing the state pointer through the generic "int" arg,
     * use a global.  This is OK because dumps are serialized externally.
     */
    state = &OS_VxWorks_SymbolDumpState;

    memset(state, 0, sizeof(*state));
    state->Sizelimit = size_limit;

    /*
    ** Open file
    */
    state->fd = open(filename, O_WRONLY | O_CREAT | O_TRUNC, 0666);
    if (state->fd < 0)
    {
        OS_DEBUG("open(%s): error: %s\n", filename, strerror(errno));
        state->StatusCode = OS_ERROR;
    }
    else
    {
        /*
        ** Iterate the symbol table
        */
        (void)symEach(sysSymTbl, OS_SymTableIterator_Impl, 0);

        close(state->fd);
    }

    /*
     * If output size was zero this means a failure of the symEach call,
     * in that it didn't iterate over anything at all.
     */
    if (state->StatusCode == OS_SUCCESS && state->CurrSize == 0)
    {
        OS_DEBUG("%s(): No symbols found!\n", __func__);
        state->StatusCode = OS_ERROR;
    }

    return state->StatusCode;
}

