osal_id_t OS_TaskGetId_Impl(void)
{
    void     *lrec;
    size_t    idx;
    osal_id_t id;

    id   = OS_OBJECT_ID_UNDEFINED;
    lrec = taskTcb(taskIdSelf());

    if (lrec != NULL)
    {
        idx = (OS_impl_task_internal_record_t *)lrec - &OS_impl_task_table[0];
        if (idx < OS_MAX_TASKS)
        {
            id = OS_global_task_table[idx].active_id;
        }
    }

    return id;
}

