static inline OS_time_t OS_TimeAdd(OS_time_t time1, OS_time_t time2)
{
    OS_time_t ostm = { time1.ticks + time2.ticks };
    return ostm;
}

static inline OS_time_t OS_TimeAssembleFromMicroseconds(int64 seconds, uint32 microseconds)
{
    OS_time_t result;
    result.ticks  = seconds * OS_TIME_TICKS_PER_SECOND;
    result.ticks += microseconds * OS_TIME_TICKS_PER_USEC;
    return result;
}

static inline OS_time_t OS_TimeAssembleFromMilliseconds(int64 seconds, uint32 milliseconds)
{
    OS_time_t result;
    result.ticks  = seconds * OS_TIME_TICKS_PER_SECOND;
    result.ticks += milliseconds * OS_TIME_TICKS_PER_MSEC;
    return result;
}

static inline OS_time_t OS_TimeAssembleFromNanoseconds(int64 seconds, uint32 nanoseconds)
{
    OS_time_t result;
    result.ticks  = seconds * OS_TIME_TICKS_PER_SECOND;
    result.ticks += nanoseconds / OS_TIME_TICK_RESOLUTION_NS;
    return result;
}

static inline OS_time_t OS_TimeAssembleFromSubseconds(int64 seconds, uint32 subseconds)
{
    OS_time_t result;
    result.ticks  = seconds * OS_TIME_TICKS_PER_SECOND;
    /* this should not round in any way, as the 32-bit input value has higher precision */
    result.ticks += ((int64)subseconds * (OS_TIME_TICKS_PER_SECOND >> 2)) >> 30;
    return result;
}

int32 OS_TimeBaseAPI_Init(void)
{
    memset(OS_timebase_table, 0, sizeof(OS_timebase_table));
    return OS_SUCCESS;
}

int32 OS_TimeBaseCreate(osal_id_t *timebase_id, const char *timebase_name, OS_TimerSync_t external_sync)
{
    int32                          return_code;
    osal_objtype_t                 objtype;
    OS_object_token_t              token;
    OS_timebase_internal_record_t *timebase;

    /*
     * Specifying a NULL sync function means the timebase is not externally synchronized.
     * In this case an appropriate OS timer will be used to generate the simulated timer tick.
     */

    /*
     ** Check Parameters
     */
    OS_CHECK_POINTER(timebase_id);
    OS_CHECK_APINAME(timebase_name);

    /*
     * Check our context.  Not allowed to use the timer API from a timer callback.
     * Just interested in the object type returned.
     */
    objtype = OS_ObjectIdToType_Impl(OS_TaskGetId_Impl());
    if (objtype == OS_OBJECT_TYPE_OS_TIMEBASE)
    {
        return OS_ERR_INCORRECT_OBJ_STATE;
    }

    /* Note - the common ObjectIdAllocate routine will lock the object type and leave it locked. */
    return_code = OS_ObjectIdAllocateNew(OS_OBJECT_TYPE_OS_TIMEBASE, timebase_name, &token);
    if (return_code == OS_SUCCESS)
    {
        timebase = OS_OBJECT_TABLE_GET(OS_timebase_table, token);

        /* Reset the table entry and save the name */
        OS_OBJECT_INIT(token, timebase, timebase_name, timebase_name);

        timebase->external_sync = external_sync;
        if (external_sync == NULL)
        {
            timebase->accuracy_usec = OS_SharedGlobalVars.MicroSecPerTick;
        }
        else
        {
            timebase->accuracy_usec = 0;
        }

        /* Now call the OS-specific implementation.  This reads info from the timer table. */
        return_code = OS_TimeBaseCreate_Impl(&token);

        /* Check result, finalize record, and unlock global table. */
        return_code = OS_ObjectIdFinalizeNew(return_code, &token, timebase_id);
    }

    return return_code;
}

int32 OS_TimeBaseCreate_Impl(const OS_object_token_t *token)
{
    /*
     * The tick_sem is a simple semaphore posted by the ISR and taken by the
     * timebase helper task (created later).
     */
    int32                               return_code;
    OS_impl_timebase_internal_record_t *local;
    OS_timebase_internal_record_t      *timebase;
    int                                 signo;
    sigset_t                            inuse;
    osal_index_t                        idx;
    uint32                              i;

    return_code = OS_SUCCESS;

    local    = OS_OBJECT_TABLE_GET(OS_impl_timebase_table, *token);
    timebase = OS_OBJECT_TABLE_GET(OS_timebase_table, *token);

    sigemptyset(&local->timer_sigset);
    local->assigned_signal = 0;
    local->handler_task    = 0;
    local->handler_mutex   = (SEM_ID)0;
    local->host_timerid    = 0;
    local->timer_state     = OS_TimerRegState_INIT;
    local->reset_flag      = false;

    /*
     * Set up the necessary OS constructs
     *
     * If an external sync function is used then there is nothing to do here -
     * we simply call that function and it should synchronize to the time source.
     *
     * If no external sync function is provided then this will set up a VxWorks
     * timer to locally simulate the timer tick using the CPU clock.
     */
    if (timebase->external_sync == NULL)
    {
        /*
         * find an RT signal that is not used by another time base object.
         * This the global lock is held here so there is no chance of
         * the underlying tables changing.
         */
        sigemptyset(&inuse);

        for (idx = 0; idx < OS_MAX_TIMEBASES; ++idx)
        {
            if (OS_ObjectIdIsValid(OS_global_timebase_table[idx].active_id)
                && OS_impl_timebase_table[idx].assigned_signal > 0)
            {
                /* mark signal as in-use */
                sigaddset(&inuse, OS_impl_timebase_table[idx].assigned_signal);
            }
        }

        for (signo = SIGRTMIN; signo <= SIGRTMAX; ++signo)
        {
            if (!sigismember(&inuse, signo))
            {
                /* signal is available, stop search */
                local->assigned_signal = signo;
                break;
            }
        }

        if (local->assigned_signal == 0)
        {
            /* no available signal for timer */
            OS_DEBUG("No free RT signals to use for simulated time base\n");
            return_code = OS_TIMER_ERR_UNAVAILABLE;
        }
        else
        {
            /*
             * Note that VxWorks appears to always send the timer signal
             * to the task that called timer_create().  This is different
             * than e.g. POSIX where the signal is sent to the process
             * and masks can be modified to direct the signal to the
             * correct task.
             *
             * Therefore, we choose the signal now, but defer calling
             * timer_create to the internal helper task.
             */
            sigaddset(&local->timer_sigset, signo);

            /*
             * Use local sigwait() wrapper as a sync function for the local task.
             */
            timebase->external_sync = OS_VxWorks_SigWait;
        }
    }

    if (return_code == OS_SUCCESS)
    {
        /*
         * Create the handler_mutex.
         * This controls access to the callback list for this timebase
         *
         * Note memory for this sem is statically allocated, so if a failure
         * occurs there is no need to free the memory later.
         */
        local->handler_mutex = semMInitialize(local->mmem, SEM_Q_PRIORITY | SEM_INVERSION_SAFE);
        if (local->handler_mutex == (SEM_ID)0)
        {
            OS_DEBUG("Error: Handler Mutex could not be initialized: errno=%d\n", errno);
            return_code = OS_TIMER_ERR_INTERNAL;
        }
    }

    /*
     * Spawn a dedicated time base handler thread
     *
     * This alleviates the need to handle expiration in the context of a signal handler -
     * The handler thread can call a BSP synchronized delay implementation as well as the
     * application callback function.  It should run with elevated priority to reduce latency.
     *
     * Note the thread will not actually start running until this function exits and releases
     * the global table lock.
     */
    if (return_code == OS_SUCCESS)
    {
        local->handler_task = taskSpawn(timebase->timebase_name,
                                        OSAL_TIMEBASE_TASK_PRIORITY,      /* priority */
                                        OSAL_TIMEBASE_TASK_OPTION_WORD,   /* task option word */
                                        OSAL_TIMEBASE_TASK_STACK_SIZE,    /* size (bytes) of stack needed */
                                        (FUNCPTR)OS_VxWorks_TimeBaseTask, /* Timebase helper task entry point */
                                        OS_ObjectIdToInteger(OS_ObjectIdFromToken(token)), /* 1st arg is ID */
                                        0,
                                        0,
                                        0,
                                        0,
                                        0,
                                        0,
                                        0,
                                        0,
                                        0);

        /* check if taskSpawn failed */
        if (local->handler_task == ((TASK_ID)ERROR))
        {
            OS_DEBUG("taskSpawn() - vxWorks errno: %d\n", errno);
            return_code = OS_TIMER_ERR_INTERNAL;
        }
        else
        {
            /*
             * Wait for the newly-spawned task to call timer_create().
             * If this is successful, then return success, otherwise
             * return failure.
             *
             * As the task runs with a high priority, it should preempt
             * this task and therefore it should probably already be
             * complete by the time execution gets here.  But for
             * multi-core machines it is possible that an extra delay
             * is necessary.
             */
            i = OSAL_TIMEBASE_REG_WAIT_LIMIT;
            while (local->timer_state == OS_TimerRegState_INIT && i > 0)
            {
                OS_TaskDelay(1);
                --i;
            }

            /*
             * If the timer wasn't fully created successfully,
             * then delete the task.
             */
            if (local->timer_state != OS_TimerRegState_SUCCESS)
            {
                OS_DEBUG("Error during timer registration\n");
                taskDelete(local->handler_task);
                return_code = OS_TIMER_ERR_INTERNAL;
            }
        }
    }

    return return_code;
}

int32 OS_TimeBaseDelete(osal_id_t timebase_id)
{
    int32             return_code;
    osal_objtype_t    objtype;
    OS_object_token_t token;

    /*
     * Check our context.  Not allowed to use the timer API from a timer callback.
     * Just interested in the object type returned.
     */
    objtype = OS_ObjectIdToType_Impl(OS_TaskGetId_Impl());
    if (objtype == OS_OBJECT_TYPE_OS_TIMEBASE)
    {
        return OS_ERR_INCORRECT_OBJ_STATE;
    }

    return_code = OS_ObjectIdGetById(OS_LOCK_MODE_EXCLUSIVE, OS_OBJECT_TYPE_OS_TIMEBASE, timebase_id, &token);
    if (return_code == OS_SUCCESS)
    {
        return_code = OS_TimeBaseDelete_Impl(&token);

        /* Complete the operation via the common routine */
        return_code = OS_ObjectIdFinalizeDelete(return_code, &token);
    }

    return return_code;
}

int32 OS_TimeBaseDelete_Impl(const OS_object_token_t *token)
{
    OS_impl_timebase_internal_record_t *local;
    int32                               return_code;

    local       = OS_OBJECT_TABLE_GET(OS_impl_timebase_table, *token);
    return_code = OS_SUCCESS;

    /* An assigned_signal value indicates the OS timer needs deletion too */
    if (local->assigned_signal > 0)
    {
        /* this also implies the sync sem needs delete too */
        timer_delete(local->host_timerid);
        local->host_timerid    = 0;
        local->assigned_signal = 0;
    }

    /*
    ** Delete the task associated with this timebase
    */
    taskDelete(local->handler_task);
    local->handler_task = 0;

    return return_code;
}

int32 OS_TimeBaseGetFreeRun(osal_id_t timebase_id, uint32 *freerun_val)
{
    int32                          return_code;
    OS_object_token_t              token;
    OS_timebase_internal_record_t *timebase;

    /* Check parameters */
    OS_CHECK_POINTER(freerun_val);

    return_code = OS_ObjectIdGetById(OS_LOCK_MODE_NONE, LOCAL_OBJID_TYPE, timebase_id, &token);
    if (return_code == OS_SUCCESS)
    {
        timebase = OS_OBJECT_TABLE_GET(OS_timebase_table, token);

        *freerun_val = timebase->freerun_time;
    }

    return return_code;
}

int32 OS_TimeBaseGetIdByName(osal_id_t *timebase_id, const char *timebase_name)
{
    int32          return_code;
    osal_objtype_t objtype;

    /* Check parameters */
    OS_CHECK_POINTER(timebase_id);
    OS_CHECK_APINAME(timebase_name);

    /*
     * Check our context.  Not allowed to use the timer API from a timer callback.
     * Just interested in the object type returned.
     */
    objtype = OS_ObjectIdToType_Impl(OS_TaskGetId_Impl());
    if (objtype == OS_OBJECT_TYPE_OS_TIMEBASE)
    {
        return OS_ERR_INCORRECT_OBJ_STATE;
    }

    return_code = OS_ObjectIdFindByName(OS_OBJECT_TYPE_OS_TIMEBASE, timebase_name, timebase_id);

    return return_code;
}

int32 OS_TimeBaseGetInfo(osal_id_t timebase_id, OS_timebase_prop_t *timebase_prop)
{
    OS_common_record_t            *record;
    int32                          return_code;
    osal_objtype_t                 objtype;
    OS_object_token_t              token;
    OS_timebase_internal_record_t *timebase;

    /* Check parameters */
    OS_CHECK_POINTER(timebase_prop);

    /*
     * Check our context.  Not allowed to use the timer API from a timer callback.
     * Just interested in the object type returned.
     */
    objtype = OS_ObjectIdToType_Impl(OS_TaskGetId_Impl());
    if (objtype == OS_OBJECT_TYPE_OS_TIMEBASE)
    {
        return OS_ERR_INCORRECT_OBJ_STATE;
    }

    memset(timebase_prop, 0, sizeof(OS_timebase_prop_t));

    return_code = OS_ObjectIdGetById(OS_LOCK_MODE_GLOBAL, LOCAL_OBJID_TYPE, timebase_id, &token);
    if (return_code == OS_SUCCESS)
    {
        record   = OS_OBJECT_TABLE_GET(OS_global_timebase_table, token);
        timebase = OS_OBJECT_TABLE_GET(OS_timebase_table, token);

        strncpy(timebase_prop->name, record->name_entry, sizeof(timebase_prop->name) - 1);
        timebase_prop->creator               = record->creator;
        timebase_prop->nominal_interval_time = timebase->nominal_interval_time;
        timebase_prop->freerun_time          = timebase->freerun_time;
        timebase_prop->accuracy              = timebase->accuracy_usec;

        return_code = OS_TimeBaseGetInfo_Impl(&token, timebase_prop);

        OS_ObjectIdRelease(&token);
    }

    return return_code;
}

int32 OS_TimeBaseGetInfo_Impl(const OS_object_token_t *token, OS_timebase_prop_t *timer_prop)
{
    return OS_SUCCESS;
}

void OS_TimeBaseLock_Impl(const OS_object_token_t *token)
{
    OS_impl_timebase_internal_record_t *impl;

    impl = OS_OBJECT_TABLE_GET(OS_impl_timebase_table, *token);

    semTake(impl->handler_mutex, WAIT_FOREVER);
}

int32 OS_TimeBaseSet(osal_id_t timebase_id, uint32 start_time, uint32 interval_time)
{
    int32                          return_code;
    osal_objtype_t                 objtype;
    OS_object_token_t              token;
    OS_timebase_internal_record_t *timebase;

    /*
     * Internally the implementation represents the interval as a
     * signed 32-bit integer, but the parameter is unsigned because a negative interval
     * does not make sense.
     *
     * Note that the units are intentionally left unspecified.  The external sync period
     * could be measured in microseconds or hours -- it is whatever the application requires.
     */
    ARGCHECK(start_time < 1000000000, OS_TIMER_ERR_INVALID_ARGS);
    ARGCHECK(interval_time < 1000000000, OS_TIMER_ERR_INVALID_ARGS);

    /*
     * Check our context.  Not allowed to use the timer API from a timer callback.
     * Just interested in the object type returned.
     */
    objtype = OS_ObjectIdToType_Impl(OS_TaskGetId_Impl());
    if (objtype == OS_OBJECT_TYPE_OS_TIMEBASE)
    {
        return OS_ERR_INCORRECT_OBJ_STATE;
    }

    return_code = OS_ObjectIdGetById(OS_LOCK_MODE_GLOBAL, OS_OBJECT_TYPE_OS_TIMEBASE, timebase_id, &token);
    if (return_code == OS_SUCCESS)
    {
        timebase = OS_OBJECT_TABLE_GET(OS_timebase_table, token);

        /* Need to take the time base lock to ensure that no ticks are currently being processed */
        OS_TimeBaseLock_Impl(&token);

        return_code = OS_TimeBaseSet_Impl(&token, start_time, interval_time);

        if (return_code == OS_SUCCESS)
        {
            /* Save the value since we were successful */
            timebase->nominal_start_time    = start_time;
            timebase->nominal_interval_time = interval_time;
        }

        OS_TimeBaseUnlock_Impl(&token);

        OS_ObjectIdRelease(&token);
    }

    return return_code;
}

int32 OS_TimeBaseSet_Impl(const OS_object_token_t *token, uint32 start_time, uint32 interval_time)
{
    OS_impl_timebase_internal_record_t *local;
    struct itimerspec                   timeout;
    int32                               return_code;
    int                                 status;

    local = OS_OBJECT_TABLE_GET(OS_impl_timebase_table, *token);

    /* There is only something to do here if we are generating a simulated tick */
    if (local->assigned_signal <= 0)
    {
        /* An externally synced timebase does not need to be set (noop) */
        return_code = OS_SUCCESS;
    }
    else
    {
        OS_VxWorks_UsecToTimespec(start_time, &timeout.it_value);
        OS_VxWorks_UsecToTimespec(interval_time, &timeout.it_interval);

        /*
        ** Program the real timer
        */
        status = timer_settime(local->host_timerid,
                               0,        /* Flags field can be zero */
                               &timeout, /* struct itimerspec */
                               NULL);    /* Oldvalue */

        if (status == OK)
        {
            /*
             * VxWorks will round the interval up to the next higher
             * system tick interval.  Sometimes this can make a substantial
             * difference in the actual time, particularly as the error
             * accumulates over time.
             *
             * timer_gettime() will reveal the actual interval programmed,
             * after all rounding/adjustments, which can be used to determine
             * the actual start_time/interval_time that will be realized.
             *
             * If this actual interval is different than the intended value,
             * it may indicate the need for better tuning on the app/config/bsp
             * side, and so a DEBUG message is generated.
             */
            status = timer_gettime(local->host_timerid, &timeout);
            if (status == OK)
            {
                return_code = OS_SUCCESS;

                local->configured_start_time = (timeout.it_value.tv_sec * 1000000) + (timeout.it_value.tv_nsec / 1000);
                local->configured_interval_time =
                    (timeout.it_interval.tv_sec * 1000000) + (timeout.it_interval.tv_nsec / 1000);

                if (local->configured_start_time != start_time)
                {
                    OS_DEBUG("WARNING: timer %lu start_time requested=%luus, configured=%luus\n",
                             OS_ObjectIdToInteger(OS_ObjectIdFromToken(token)),
                             (unsigned long)start_time,
                             (unsigned long)local->configured_start_time);
                }
                if (local->configured_interval_time != interval_time)
                {
                    OS_DEBUG("WARNING: timer %lu interval_time requested=%luus, configured=%luus\n",
                             OS_ObjectIdToInteger(OS_ObjectIdFromToken(token)),
                             (unsigned long)interval_time,
                             (unsigned long)local->configured_interval_time);
                }
            }
            else
            {
                return_code = OS_ERROR;

                OS_DEBUG("WARNING: timer %lu timer_gettime() failed - timer not configured properly?\n",
                         OS_ObjectIdToInteger(OS_ObjectIdFromToken(token)));
            }
        }
        else
        {
            return_code = OS_TIMER_ERR_INVALID_ARGS;
        }
    }

    if (!local->reset_flag && return_code == OS_SUCCESS)
    {
        local->reset_flag = true;
    }

    return return_code;
}

void OS_TimeBaseUnlock_Impl(const OS_object_token_t *token)
{
    OS_impl_timebase_internal_record_t *impl;

    impl = OS_OBJECT_TABLE_GET(OS_impl_timebase_table, *token);

    semGive(impl->handler_mutex);
}

void OS_TimeBase_CallbackThread(osal_id_t timebase_id)
{
    OS_TimerSync_t                 syncfunc;
    OS_timebase_internal_record_t *timebase;
    OS_timecb_internal_record_t   *timecb;
    OS_common_record_t            *record;
    OS_object_token_t              token;
    OS_object_token_t              cb_token;
    uint32                         tick_time;
    uint32                         spin_cycles;
    int32                          saved_wait_time;

    /*
     * Register this task as a time base handler.
     * Application code MUST NOT attempt to configure timers from the context of a
     * timer callback, otherwise deadlock is possible.  Additional checks prevent this.
     *
     */
    OS_TaskRegister_Impl(timebase_id);

    /* Grab the relevant info from the global structure */
    if (OS_ObjectIdGetById(OS_LOCK_MODE_GLOBAL, OS_OBJECT_TYPE_OS_TIMEBASE, timebase_id, &token) != 0)
    {
        /* Something went wrong - abort this thread */
        return;
    }

    record   = OS_OBJECT_TABLE_GET(OS_global_timebase_table, token);
    timebase = OS_OBJECT_TABLE_GET(OS_timebase_table, token);

    syncfunc    = timebase->external_sync;
    spin_cycles = 0;

    OS_ObjectIdRelease(&token);

    while (1)
    {
        /*
         * Call the sync function - this will pend for some period of time
         * and return the amount of elapsed time in units of "timebase ticks"
         */
        tick_time = (*syncfunc)(timebase_id);

        /*
         * The returned tick_time should be nonzero.  If the sync function
         * returns zero, then it means something went wrong and it is not
         * known how many ticks have elapsed.
         *
         * This can validly occur, for instance, if the underlying wait
         * operation was interrupted for some reason, e.g. EINTR or EAGAIN
         * on a POSIX-like OS.
         *
         * In some instances it is appropriate to simply call the
         * function again.  However, since this task typically runs as a
         * high-priority thread, it is prudent to limit such spinning.
         */
        if (tick_time != 0)
        {
            /* nominal case - reset counter */
            spin_cycles = 0;
        }
        else if (spin_cycles < OS_TIMEBASE_SPIN_LIMIT)
        {
            /* off-nominal but OK for now */
            ++spin_cycles;
        }
        else
        {
            /*
             * Spin-loop detected.
             * Just call OS_TaskDelay_Impl() to yield the CPU.
             * generate a debug warning only on the first time
             * so the operator knows this is happening.
             */
            OS_TaskDelay_Impl(10);

            if (spin_cycles == OS_TIMEBASE_SPIN_LIMIT)
            {
                ++spin_cycles;
                OS_DEBUG("WARNING: Timebase Sync Spin Loop detected\n");
            }
        }

        OS_TimeBaseLock_Impl(&token);

        /*
         * After waiting, check that our ID still matches
         * If not then it means this time base got deleted....
         */
        if (!OS_ObjectIdEqual(timebase_id, record->active_id))
        {
            OS_TimeBaseUnlock_Impl(&token);
            break;
        }

        timebase->freerun_time += tick_time;
        if (OS_ObjectIdGetById(OS_LOCK_MODE_NONE, OS_OBJECT_TYPE_OS_TIMECB, timebase->first_cb, &cb_token) == 0)
        {
            do
            {
                timecb             = OS_OBJECT_TABLE_GET(OS_timecb_table, cb_token);
                saved_wait_time    = timecb->wait_time;
                timecb->wait_time -= tick_time;
                while (timecb->wait_time <= 0)
                {
                    timecb->wait_time += timecb->interval_time;

                    /*
                     * Only allow the "wait_time" underflow to go as far negative as one interval time
                     * This prevents a cb "interval_time" of less than the timebase interval_time from
                     * accumulating infinitely
                     */
                    if (timecb->wait_time < -timecb->interval_time)
                    {
                        ++timecb->backlog_resets;
                        timecb->wait_time = -timecb->interval_time;
                    }

                    /*
                     * Only give the callback if the wait_time actually transitioned from positive to negative.
                     * This allows one-shot operation where the API sets the "wait_time" positive but keeps
                     * the "interval_time" at zero.  With the interval_time at zero the wait time will never
                     * go positive again unless the API sets it again.
                     */
                    if (saved_wait_time > 0 && timecb->callback_ptr != NULL)
                    {
                        (*timecb->callback_ptr)(OS_ObjectIdFromToken(&cb_token), timecb->callback_arg);
                    }

                    /*
                     * Do not repeat the loop unless interval_time is configured.
                     */
                    if (timecb->interval_time <= 0)
                    {
                        break;
                    }
                }

            } while (OS_ObjectIdGetById(OS_LOCK_MODE_NONE, OS_OBJECT_TYPE_OS_TIMECB, timecb->next_cb, &cb_token)
                         == OS_SUCCESS
                     && !OS_ObjectIdEqual(OS_ObjectIdFromToken(&cb_token), timebase->first_cb));
        }

        OS_TimeBaseUnlock_Impl(&token);
    }
}

static inline int8_t OS_TimeCompare(OS_time_t time1, OS_time_t time2)
{
    return OS_TimeGetSign(OS_TimeSubtract(time1, time2));
}

static inline bool OS_TimeEqual(OS_time_t time1, OS_time_t time2)
{
    return (time1.ticks == time2.ticks);
}

OS_time_t OS_TimeFromRelativeMilliseconds(int32 relative_msec)
{
    OS_time_t abs_time = OS_TIME_ZERO;

    if (relative_msec == OS_CHECK)
    {
        abs_time = OS_TIME_ZERO;
    }
    else if (relative_msec > 0)
    {
        OS_GetLocalTime_Impl(&abs_time);
        abs_time = OS_TimeAdd(abs_time, OS_TimeFromTotalMilliseconds(relative_msec));
    }
    else
    {
        abs_time = OS_TIME_MAX;
    }

    return abs_time;
}

static inline OS_time_t OS_TimeFromTotalMicroseconds(int64 tm)
{
    /* SAD: Overflow is not considered a concern because tm would need to be over 29,227 years in microseconds */
    OS_time_t ostm = { tm * OS_TIME_TICKS_PER_USEC };
    return ostm;
}

static inline OS_time_t OS_TimeFromTotalMilliseconds(int64 tm)
{
    OS_time_t ostm = { tm * OS_TIME_TICKS_PER_MSEC };
    return ostm;
}

static inline OS_time_t OS_TimeFromTotalNanoseconds(int64 tm)
{
    OS_time_t ostm = { tm / OS_TIME_TICK_RESOLUTION_NS };
    return ostm;
}

static inline OS_time_t OS_TimeFromTotalSeconds(int64 tm)
{
    OS_time_t ostm = { tm * OS_TIME_TICKS_PER_SECOND };
    return ostm;
}

static inline int64 OS_TimeGetFractionalPart(OS_time_t tm)
{
    return (tm.ticks % OS_TIME_TICKS_PER_SECOND);
}

static inline uint32 OS_TimeGetMicrosecondsPart(OS_time_t tm)
{
    return (uint32)OS_TimeGetFractionalPart(tm) / OS_TIME_TICKS_PER_USEC;
}

static inline uint32 OS_TimeGetMillisecondsPart(OS_time_t tm)
{
    return (uint32)OS_TimeGetFractionalPart(tm) / OS_TIME_TICKS_PER_MSEC;
}

static inline uint32 OS_TimeGetNanosecondsPart(OS_time_t tm)
{
    return (uint32)OS_TimeGetFractionalPart(tm) * OS_TIME_TICK_RESOLUTION_NS;
}

static inline int8_t OS_TimeGetSign(OS_time_t time)
{
    return (time.ticks > 0) - (time.ticks < 0);
}

static inline uint32 OS_TimeGetSubsecondsPart(OS_time_t tm)
{
    /*
     * This computation avoids a 32-bit left shift which may not be implemented.
     *
     * It also must round up, otherwise this may result in a value one
     * less than the original when converted back to usec again.
     */
    int64 frac = (OS_TimeGetFractionalPart(tm) << 30) + (OS_TIME_TICKS_PER_SECOND >> 2);
    return (uint32)((frac - 1) / (OS_TIME_TICKS_PER_SECOND >> 2));
}

static inline int64 OS_TimeGetTotalMicroseconds(OS_time_t tm)
{
    return (tm.ticks / OS_TIME_TICKS_PER_USEC);
}

static inline int64 OS_TimeGetTotalMilliseconds(OS_time_t tm)
{
    return (tm.ticks / OS_TIME_TICKS_PER_MSEC);
}

static inline int64 OS_TimeGetTotalNanoseconds(OS_time_t tm)
{
    return (tm.ticks * OS_TIME_TICK_RESOLUTION_NS);
}

static inline int64 OS_TimeGetTotalSeconds(OS_time_t tm)
{
    return (tm.ticks / OS_TIME_TICKS_PER_SECOND);
}

static inline OS_time_t OS_TimeSubtract(OS_time_t time1, OS_time_t time2)
{
    OS_time_t ostm = { time1.ticks - time2.ticks };
    return ostm;
}

int32 OS_TimeToRelativeMilliseconds(OS_time_t time)
{
    int64     relative_msec;
    OS_time_t curr_time = OS_TIME_ZERO;

    /*
     * This is an optimization that assumes all negative time values are
     * in the past - no need to read the clock to figure that out.
     *
     * Also OS_TIME_MAX is equivalent to pend forever, and does not
     * need to read the clock either.
     */
    if (OS_TimeGetSign(time) <= 0 || OS_TimeEqual(time, OS_TIME_MAX))
    {
        curr_time = time;
    }
    else
    {
        OS_GetLocalTime_Impl(&curr_time);
        curr_time = OS_TimeSubtract(time, curr_time);
    }

    if (OS_TimeGetSign(curr_time) <= 0)
    {
        /* map this to a polling op (OS_CHECK) */
        relative_msec = OS_CHECK;
    }
    else
    {
        /* note this result is 64 bits, as this can exceed int32 potentially */
        relative_msec = OS_TimeGetTotalMilliseconds(curr_time);

        /* Just in case: cap the value at INT32_MAX */
        if (relative_msec > INT32_MAX)
        {
            /* map this to an indefinite block (OS_PEND) */
            relative_msec = OS_PEND;
        }
    }

    return relative_msec;
}

